function visitRelated(id){const d=project.docs.find(d=>d.id===id);if(!d)return;crossNavigation.push({projectId:project.id,selected,type,tab,query,special,linkedDocId,galleryFilters:structuredClone(galleryFilters),tables:{...selectedTables},scroll:captureScroll(document)});if(crossNavigation.length>30)crossNavigation.shift();selected=d.id;type=d.type;tab=['item','skill','term'].includes(type)?'list':type==='narrative'?'story':'preview';query='';linkedDocId='';special=null;render();}
