function toast(msg,error=false){const n=document.createElement('div');n.className='toast'+(error?' error':'');n.textContent=msg;document.querySelector('#toasts').append(n);setTimeout(()=>n.remove(),4500);}
function transaction(store,mode,fn){if(!nativeStore)throw Error('插件项目服务未连接');return nativeStore.transaction(store,mode,fn);}
let saveStatus='saved';const saveLabel=()=>({saved:'已保存到本地项目目录',pending:'有修改待保存',saving:'正在保存…',failed:'保存失败，修改尚未写入'})[saveStatus];function showSaveStatus(){const el=document.querySelector('.save-state');if(el)el.textContent=saveLabel();}
const putProject=createProjectWriter(async p=>{if(p===project){saveStatus='saving';showSaveStatus();}try{const result=await nativeStore.saveProject(p);if(p===project){saveStatus=saveTimer?'pending':'saved';showSaveStatus();}return result;}catch(error){if(p===project){saveStatus='failed';showSaveStatus();}throw error;}});
const getFile=id=>transaction('files','readonly',s=>s.get(id));
async function addFile(blob,name){const id=uid();await transaction('files','readwrite',s=>s.put({id,blob,name}));objectURLs.set(id,await blobDataURL(blob));return id;}
async function warmFiles(){const d=current();if(!d||['item','skill','term'].includes(type)&&tab==='list')return;const rows=[...documentResources(d).map(r=>r.resource),...(d.images||[])];await Promise.all(rows.slice(0,30).filter(r=>r?.fileId).map(r=>objectURLs.ensure(r.fileId).catch(()=>null)));}

function markDirty(){saveStatus='pending';const owner=project;const el=document.querySelector('.save-state');if(el)el.innerHTML='<span class="save-dot"></span>正在保存…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist(owner),450);}
async function persist(owner=project){clearTimeout(saveTimer);saveTimer=null;try{await putProject(owner);const el=owner===project?document.querySelector('.save-state'):null;if(el)el.innerHTML='<span class="save-dot"></span>'+saveLabel();return true;}catch(err){toast('保存失败，当前修改尚未写入：'+err.message,true);const el=document.querySelector('.save-state');if(el)el.textContent='保存失败';return false;}}
function setDraft(field,value){const d=current();if(!d)return;d.draft||={};d.draft[field]=value;markDirty();}
function activeAction(){const d=current();return d?.draft?.action||TYPES[d?.type||'script'].actions[0];}
function docDisplayName(d){return d.type==='character'?(String(d.character?.name||'').trim()||'未命名人物'):d.title;}
function docButton(d){const row=`<button class="doc-item ${selected===d.id&&!special?'active':''}" data-action="select" data-id="${e(d.id)}">${icon(d.type==='asset'?'image':'file')}<span><strong>${e(docDisplayName(d))}</strong><small><i class="mini-dot ${d.status==='draft'?'draft':''}"></i>${d.status==='confirmed'?'已确认':d.type==='character'?'待修改':'草稿'}<span class="sep"> · </span>${when(d.updated)}</small></span></button>`;return d.type==='character'?`<div class="character-directory-row"><div class="character-doc-frame ${selected===d.id&&!special?'active':''}">${row}<button class="character-properties-btn" data-character-properties="${e(d.id)}" title="属性配置" aria-label="属性配置：${e(docDisplayName(d))}">${icon('settings')}<span>属性</span></button></div><div class="character-directory-actions"><button class="character-move-btn" data-move-character="${e(d.id)}" title="移动人物" aria-label="移动人物：${e(docDisplayName(d))}">${icon('folder')}<span>移动</span></button><button  class="character-move-btn character-delete-btn" data-delete-character="${e(d.id)}" title="删除人物" aria-label="删除人物：${e(docDisplayName(d))}">${icon('trash')}<span>删除</span></button></div></div>`:`<div class="character-directory-row">${row}<div class="character-directory-actions"><button class="character-move-btn" data-move-document="${e(d.id)}">${icon('folder')}<span>移动</span></button><button class="character-move-btn character-delete-btn" data-delete-document="${e(d.id)}">${icon('trash')}<span>删除</span></button></div></div>`;}
function renderDirectory(){if(type==='ui'){const docs=project.docs.filter(d=>d.type==='ui'&&(d.title||'').toLowerCase().includes(query.toLowerCase()));return `<div class="directory-head"><div class="section-title"><h2>UI 界面</h2><button class="btn" data-action="new">＋ 新增界面</button></div><input id="search" placeholder="搜索界面…" value="${e(query)}"></div><div class="directory-scroll">${docs.map(d=>`<div class="ue-directory-entry">${docButton(d)}<button class="btn ue-assets-entry" data-ue="assets" data-doc="${e(d.id)}">素材</button></div>`).join('')}</div>`;}if(aggregateType(type))return renderAggregateDirectory(project,type,{selected:activeTable(),query,icon});if(type==='skill')return renderSkillDirectory();const meta=TYPES[type],docs=project.docs.filter(d=>d.type===type&&(docDisplayName(d)+' '+d.md).toLowerCase().includes(query.toLowerCase()));const groups=directoryGroups(type,docs,project.folders?.[type]||[]);return `<div class="directory-head"><div class="section-title"><h2>${meta.label}</h2>${type==='character'?'':`<button class="icon-btn" data-action="new" title="新建${meta.label}" aria-label="新建${meta.label}">${icon('plus')}</button>`}</div><div class="search">${icon('search')}<input id="search" placeholder="搜索${meta.label}…" value="${e(query)}" aria-label="搜索目录"></div></div><div class="directory-tools"><span>全部内容 <span class="sep">/</span> ${docs.length}</span>${type==='character'?'':`<button data-action="folder" title="新建分类" aria-label="新建分类">${icon('folder')}</button>`}</div><div class="directory-scroll">${groups.map(g=>{const fixed=(type==='script'&&FIXED_SCRIPT_FOLDERS.includes(g))||(type==='character'&&CHARACTER_FOLDERS.includes(g))||(type!=='script'&&g==='默认分类');const members=docs.filter(d=>(d.folder||'未分类')===g);if(type==='item'&&(g==='默认分类'||g==='未分类'))return members.map(docButton).join('');return `<button class="folder-head" data-action="toggle-folder" data-folder="${e(g)}" ${fixed?'title="固定文件夹，不可删除或改名"':''}>${icon('down')}${icon('folder')}<span>${e(g)}</span>${fixed?'<span class="fixed-folder-label" aria-label="固定文件夹">'+icon('lock')+'</span>':''}<span class="folder-count">${members.length}</span></button><div data-folder-content="${e(g)}">${members.map(docButton).join('')}${type==='character'?`<button class="folder-empty" data-action="new-in-folder" data-folder="${e(g)}">${icon('plus')}新建人物</button>`:members.length?'':`<button class="folder-empty" data-action="new-in-folder" data-folder="${e(g)}">${icon('plus')}添加内容</button>`}</div>`;}).join('')||'<div class="empty"><p>还没有内容<br>点击上方 + 开始创建</p></div>'}</div><div class="directory-foot">${icon('file')} ${type==='character'?'在分类内创建与管理人物':'Markdown 原生资料'}</div>`;}
function renderSkillDirectory(){const docs=project.docs.filter(d=>d.type==='skill'&&(d.title+' '+d.md).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>Number(isFixedSkill(b))-Number(isFixedSkill(a)));return `<div class="directory-head"><div class="section-title"><h2>技能</h2><button class="icon-btn" data-action="new" title="新建技能" aria-label="新建技能">${icon('plus')}</button></div><div class="search">${icon('search')}<input id="search" placeholder="搜索技能…" value="${e(query)}" aria-label="搜索目录"></div></div><div class="directory-tools"><span>全部内容 / ${docs.length}</span></div><div class="directory-scroll">${docs.map(d=>`<button class="doc-item ${selected===d.id?'active':''}" data-action="select" data-id="${e(d.id)}">${icon('spark')}<span><strong>${e(d.title)}</strong></span></button>`).join('')}</div><div class="directory-foot">${icon('file')}技能模板与资料</div>`;}
function rememberNavigation(){if(project)saveView(localStorage,sessionStorage,{projectId:project.id,type,selected:selected||null,tab,special,query});}
function restoreNavigation(saved){const view=resolveNavigation(project,saved||readView(localStorage,'nw-view:'+project.id)||{});type=view.type;selected=view.selected;tab=view.tab;special=['images','audios'].includes(view.special)?null:view.special;query=view.query;}
function render(){
  const viewKey=JSON.stringify([project?.id,type,selected,tab,special]);const scrollState=app.dataset.viewKey===viewKey?captureScroll(document):null;
  const d=current();if(!d&&!special){selected=project.docs.find(x=>x.type===type)?.id;}
  rememberNavigation();
  app.innerHTML=`<div class="shell ${['images','audios'].includes(special)?'gallery-shell':''}"><div class="brand"><span class="logo">${icon('layers')}</span><div><strong>管理工坊</strong><small>MANAGEMENT STUDIO</small></div></div><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" data-action="mobile" aria-label="展开目录">${icon('menu')}</button><span class="project-crumb">${e(project.name)}</span><span class="project-crumb">/</span><b>${special?({settings:'项目设置',tasks:'生成记录',trash:'垃圾桶',images:'图片素材管理',audios:'音频素材管理'}[special]):TYPES[type].label}</b></div><div class="top-actions"><span class="save-state"><span class="save-dot"></span>${saveLabel()}</span><button class="btn primary" data-action="save-disk" ${savingToDisk?'disabled':''}>${icon('download')}<span>${savingToDisk?'保存中…':'保存'}</span></button><button class="btn" data-action="import">${icon('upload')}<span>导入</span></button><button class="btn" data-action="export">${icon('download')}<span>导出项目</span></button><button class="icon-btn" data-action="help" title="使用说明" aria-label="使用说明">${icon('book')}</button></div></header><aside class="sidebar"><button class="project-picker" data-action="projects"><span class="project-emblem">${icon('globe')}</span><span><strong>${e(project.name)}</strong><small>游戏内容工作空间</small></span>${icon('down')}</button><div class="nav-caption">项目内容 · CONTENT</div>${WORKFLOW.map(([k,mode,label,glyph])=>`<button class="nav-item ${type===k&&tab===mode&&!special?'active':''}" data-action="type" data-type="${k}" data-mode="${mode}" title="${label}">${icon(glyph)}<span>${label}</span><span class="count">${project.docs.filter(d=>d.type===k).length.toString().padStart(2,'0')}</span></button>`).join('')}<div class="nav-divider"></div><button class="nav-item ${special==='tasks'?'active':''}" data-action="page" data-page="tasks" title="生成记录">${icon('clock')}<span>生成记录</span><span class="count">${((project.generationJobs||[]).length+project.tasks.length).toString().padStart(2,'0')}</span></button><button class="nav-item ${special==='trash'?'active':''}" data-action="open-trash" title="垃圾桶">${icon('trash')}<span>垃圾桶</span></button><div class="sidebar-bottom"><button class="nav-item ${special==='settings'?'active':''}" data-action="page" data-page="settings" title="项目设置">${icon('settings')}<span>项目设置</span></button><div class="local-note"><b>${icon('lock')} 本地优先，创作自由</b>资料保存在本机项目目录<br>定期导出，留住每次灵感</div></div></aside><aside class="directory ${mobileOpen?'visible':''}">${renderDirectory()}</aside><main class="workspace">${renderStudioBar(project,current())}${special?renderSpecial():renderWorkspace()}</main></div>`;
  objectURLs.observe(app);app.dataset.viewKey=viewKey;restoreScroll(document,scrollState);requestAnimationFrame(()=>{if(app.dataset.viewKey===viewKey)restoreScroll(document,scrollState);});
}
function renderWorkspace(){const d=current();if(['item','skill'].includes(type)&&['icons','sounds'].includes(tab))return tab==='icons'?renderImageReview(project,objectURLs,{...galleryFilters,type,lockType:true,tableId:activeTable(),selected:[...gallerySelection]}):renderLinkedMedia(project,type,tab,{urls:objectURLs,icon,query,tableId:activeTable(),docId:linkedDocId,status:soundStatus,selected:[...soundSelection]});if(['item','skill','term'].includes(type)&&['list','preview'].includes(tab))return renderPlanningList(project,type,{query,icon,tableId:activeTable()});if(type==='narrative'&&tab!=='story'&&d)return renderDialogue(d,project,{urls:objectURLs,running:dialogueRunning,progress:dialogueProgress});if(type==='skill'&&tab!=='list')return renderSkills(project,{busy:busy||skillBatchRunning,query,urls:objectURLs,icon});const form=doc=>renderContentForm(doc,{docs:project.docs,icon,urls:objectURLs,refs:renderRefs(doc),history:renderHistory(doc),composer:renderComposer(doc,referenceDocs(doc,project.docs),doc.images||[]),participants:isChapter(doc)?renderParticipants(doc):''});if(type==='item')return renderItems(project,{query,busy,urls:objectURLs,icon})+(d?'<details id="item-detail" class="item-detail"><summary>道具详细资料</summary>'+form(d)+'</details>':'');if(type==='narrative'&&tab==='story'&&!d)return renderStoryManager(project,selected);if(!d)return '<div class="wide-page">'+emptyState('新建策划内容','填写适合你的游戏的字段，所有内容均可留空。','new','新建内容')+'</div>';if(d.type==='ui')return renderUIEditor(d,objectURLs,form(d));if(d.type==='character')return renderCharacter(d);if(type==='narrative'&&tab==='story')return renderStoryManager(project,selected)+form(d)+`<section class="char-panel"><h2>章节 / 段落剧本</h2><label class="char-field">剧本正文<textarea data-dialogue-source rows="10" placeholder="先填写大纲，再生成或填写 人物（语气）：台词。">${e(d.dialogue?.source||'')}</textarea></label><button class="btn primary" data-story-generate>按大纲生成台词</button><button class="btn" data-action="type" data-type="narrative" data-mode="dialogue">进入人物对白与配音</button></section>`;return form(d);} 
function renderParticipants(d){const people=project.docs.filter(x=>x.type==='character'&&(d.participants||[]).includes(x.id));return '<section class="chapter-people"><div class="chapter-people-head"><strong>'+icon('users')+'主要参与人物</strong><button class="btn" data-action="choose-participants">'+icon('plus')+'选择人物</button></div><div class="people-chips">'+(people.length?people.map(p=>'<button class="person-chip" data-action="select" data-id="'+e(p.id)+'">'+icon('person')+e(p.title)+icon('arrow')+'</button>').join(''):'<span class="text-muted">选择本章参与人物，点击人物可跳转查看资料。</span>')+'</div></section>';}
function showParticipants(){const d=current(),people=project.docs.filter(x=>x.type==='character');showModal('选择主要参与人物','<p class="notice">勾选本章参与人物。人物设定将作为 AI 参考，点击人物入口可直接打开资料。</p>'+people.map(p=>'<label class="check-row"><input type="checkbox" name="participant" value="'+e(p.id)+'" '+((d.participants||[]).includes(p.id)?'checked':'')+'><span>'+e(p.title)+'<small>'+e(p.folder||'未分类')+'</small></span></label>').join('')+(people.length?'':'<p class="text-muted">请先在人物板块创建人物，再回到章节选择。</p>'),'<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-participants">保存参与人物</button>');}
function renderStage(d){
  if(tab==='refs')return renderRefs(d);
  if(tab==='history')return renderHistory(d);
  const media=d.media&&objectURLs.get(d.media.fileId);return `${['music','sound'].includes(d.type)?'<p class="notice">支持音频上传试听，以及使用文本 AI 整理需求和提示词。直接生成音频的接口将在后续接入。</p>':''}${['asset','music','sound'].includes(d.type)&&!media?`<button class="upload-card" style="width:100%;min-height:150px;margin-bottom:20px" data-action="upload-media">${icon('upload')}${['music','sound'].includes(d.type)?'上传音频文件':'上传素材文件'}<small>${['music','sound'].includes(d.type)?'MP3 / WAV / OGG 等音频格式':'图片、音频或视频'}</small></button>`:''}${media?`<div class="asset-preview">${d.media.mime?.startsWith('audio/')?`<audio controls src="${media}"></audio>`:d.media.mime?.startsWith('video/')?`<video controls style="max-width:100%;max-height:400px" src="${media}"></video>`:`<img src="${media}" alt="${e(d.title)}" data-action="zoom" data-file="${e(d.media.fileId)}">`}</div><div class="asset-toolbar"><small>${e(d.media.name)}</small><div><button class="btn" data-action="download-media">${icon('download')}下载原文件</button><button class="btn subtle" data-action="upload-media">替换素材</button></div></div>`:''}<article class="document">${markdown(d.md)}${(d.images||[]).length?`<div class="body-ref"><h3>关联参考图 · ${d.images.length}</h3><div class="thumb-strip">${d.images.map(r=>`<button data-action="zoom" data-file="${e(r.fileId)}" title="${e(r.name)}">${objectURLs.has(r.fileId)?`<img src="${objectURLs.get(r.fileId)}" alt="${e(r.name)}">`:'图片缺失'}</button>`).join('')}</div></div>`:''}</article>`;
}
function renderComposer(){return '<section class="composer native-gpt-handoff"><div class="composer-label">'+icon('spark')+' GPT 创作</div><p class="text-muted">在下方原生 GPT 对话中直接描述需求，文字和图片均由当前 GPT 生成。</p><button class="btn primary" data-action="run-ai">'+icon('send')+'将当前策划交给 GPT</button></section>';}

function renderRefs(d){const refs=referenceDocs(d,project.docs);return `<h3 class="panel-title">参考资料</h3><p class="panel-desc">将设定与图片加入本次创作依据。勾选的图片会在支持图片输入的任务中实际提交。</p><div style="display:flex;gap:8px;margin-bottom:20px"><button class="btn" data-action="choose-refs">${icon('link')}关联设定文档</button><button class="btn" data-action="upload-ref">${icon('plus')}添加参考图</button><button class="btn" data-action="library-ref">${icon('image')}从素材库选择</button></div>${refs.length?`<div class="related-list" style="margin-bottom:24px">${refs.map(r=>`<div class="related-row">${icon(TYPES[r.type].icon)}<span>${e(r.title)}</span><small>${TYPES[r.type].label}</small><button class="icon-btn" data-action="remove-ref" data-id="${e(r.id)}" title="移除引用" aria-label="移除引用">${icon('close')}</button></div>`).join('')}</div>`:''}<div class="reference-grid">${(d.images||[]).map((r,i)=>`<div class="ref-card">${objectURLs.has(r.fileId)?`<img class="ref-image" src="${objectURLs.get(r.fileId)}" alt="${e(r.name)}" data-action="zoom" data-file="${e(r.fileId)}">`:'<div class="empty">图片文件缺失</div>'}<div class="ref-content"><strong>${e(r.name)}</strong><textarea data-ref-note="${i}" placeholder="参考什么？例如：色彩、材质、建筑结构" aria-label="参考用途">${e(r.note||'')}</textarea><textarea data-ref-avoid="${i}" placeholder="不参考什么？（可选）" aria-label="不参考的部分">${e(r.avoid||'')}</textarea><div class="ref-meta"><label><input type="checkbox" data-ref-enabled="${i}" ${r.enabled!==false?'checked':''}>本次使用</label><button class="icon-btn" data-action="remove-image" data-index="${i}" title="移除参考图" aria-label="移除参考图">${icon('trash')}</button></div></div></div>`).join('')}<button class="upload-card" data-action="upload-ref">${icon('plus')}添加参考图<small>PNG / JPG / WebP · 每张不超过 10 MB</small></button></div>`;}
function renderHistory(d){return `<h3 class="panel-title">版本与候选结果</h3><p class="panel-desc">正式内容更新前保留快照；AI 结果经确认后再采纳。</p><button class="btn" data-action="snapshot" style="margin-bottom:20px">${icon('plus')}保存当前快照</button>${[...(d.versions||[])].reverse().map(v=>`<div class="history-card"><div class="history-head"><strong>${e(v.label||'内容快照')}</strong><small>${when(v.time)}</small></div><div class="history-body">${v.fileId?`<div class="candidate">${objectURLs.has(v.fileId)?`<img src="${objectURLs.get(v.fileId)}" alt="历史素材">`:'素材文件缺失'}</div>`:`<div class="candidate document">${markdown(v.md||'')}</div>`}<div class="history-actions"><button class="btn" data-action="restore" data-version="${e(v.id)}">${icon('refresh')}恢复此版本</button><button class="btn subtle" data-action="version-source" data-version="${e(v.id)}">查看 MD</button></div></div></div>`).join('')}${project.tasks.filter(t=>t.docId===d.id).slice().reverse().map(renderTask).join('')||(!(d.versions||[]).length?emptyState('还没有版本记录','保存快照或完成一次 AI 生成后，会在这里保留记录。'):'')}`;}
function renderTask(t){return `<div class="history-card"><div class="history-head"><div><strong>${e(t.action)} · ${e(t.title)}</strong><small style="display:block;margin-top:5px">${e(t.model)} · ${when(t.time)}</small></div><span class="task-status ${t.status==='failed'?'failed':''}">${({running:'生成中',done:'候选结果',adopted:'已采纳',failed:'失败',cancelled:'已取消'})[t.status]||t.status}</span></div><div class="history-body">${t.error?`<div class="task-error">${e(t.error)}</div>`:''}${t.result?`<div class="candidate document">${markdown(t.result)}</div>`:''}${t.fileId?`<div class="candidate"><img src="${objectURLs.get(t.fileId)||''}" alt="AI 生成候选" data-action="zoom" data-file="${e(t.fileId)}"></div>`:''}${t.status==='running'?`<div class="busy-line">${icon('refresh','spin')}正在等待模型返回…</div>`:''}<div class="history-actions">${t.status==='done'?`<button class="btn primary" data-action="adopt" data-task="${e(t.id)}">${icon('check')}采纳结果</button><button class="btn" data-action="continue-task" data-task="${e(t.id)}">${icon('edit')}继续修改</button>`:''}<button class="btn subtle" data-action="task-input" data-task="${e(t.id)}">查看本次输入</button></div></div></div>`;}
function emptyState(title,desc,action,label){return `<div class="empty"><div class="empty-icon">${icon('layers')}</div><h3>${title}</h3><p>${desc}</p>${action?`<button class="btn primary" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`;}
function renderSpecial(){if(special==='audios')return renderAudioReview(project,objectURLs,{query:audioQuery,selected:[...audioSelection]});if(special==='images')return renderImageReview(project,objectURLs,{...galleryFilters,selected:[...gallerySelection]});if(special==='trash')return renderRecycleBin();if(special==='tasks')return renderJobs(project);if(special==='legacy-tasks')return `<div class="wide-page"><h2 class="panel-title">生成记录</h2><p class="panel-desc">查看模型输入、参考资料与候选结果。API 密钥不会写入记录。</p>${project.tasks.slice().reverse().map(renderTask).join('')||emptyState('还没有生成任务','打开任意内容，添加要求并提交 AI，即可开始创作。','page','项目设置')}</div>`;
  return `<div class="wide-page"><h2 class="panel-title">项目设置</h2><p class="panel-desc">管理项目资料、模型连接与备份。</p><div class="settings-layout"><div class="settings-section"><h3>项目信息</h3><div class="field"><label>项目名称</label><input id="project-name" value="${e(project.name)}" maxlength="80"></div><div class="field"><label>项目简介</label><input id="project-description" value="${e(project.description||'')}" maxlength="300"></div><button class="btn primary" data-action="save-project">保存项目信息</button></div><div class="settings-section"><h3>AI 创作</h3><p>文字和图片使用当前 GPT 对话，无需配置 API。配音使用本地 IndexTTS 2.5。</p>${renderMediaAPISettings()}</div><div class="settings-section"><h3>资料与备份</h3><div class="settings-row"><div><strong>本地保存位置</strong><small>${e(project.saveFolderName||nativeStore.root)}</small></div><button class="btn" data-action="save-disk">保存项目</button></div><div class="settings-row"><div><strong>项目全量资料.md</strong><small>合并全部正文、人物字段、参考与历史，供 GPT 一次读取；空字段不强制填写</small></div><button class="btn" data-action="export-overview">导出 AI 总览</button></div>${archivedProjects.length?'<button class="btn" data-action="archived-projects">恢复历史项目备份</button>':''}<div class="settings-row"><div><strong>Markdown 是正式内容</strong><small>${project.docs.length} 份文档 · ${project.tasks.length} 条生成记录 · 图片随项目包导出</small></div><button class="btn" data-action="export">导出 ZIP</button></div><div class="settings-row"><div><strong>从文件继续创作</strong><small>导入 MD 文档或由本工具导出的项目 ZIP</small></div><button class="btn" data-action="import">导入文件</button></div><p class="text-muted">资料和附件保存在本机项目目录，GPT 与工作台读取同一份资料。导出 ZIP 可用于备份和团队交换。</p></div></div></div>`;
}
function showModal(title,body,footer=''){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!modal.open)modal.showModal();objectURLs.observe(document);}
const closeModal=()=>modal.close();
function field(label,id,value='',extra=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" value="${e(value)}" ${extra}></div>`;}
function showNew(folder=''){if(aggregateType(type)){showModal('新增'+tableLabel(type),field('名称','new-title','','placeholder="输入名称" maxlength="100"')+'<p class="text-muted">新增一行到当前表，并在总表中同步显示。</p>','<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="create-doc">添加到表格</button>');document.querySelector('#new-title').focus();return;}showModal('新建'+TYPES[type].label,`${field(type==='character'?'姓名':'名称','new-title','','placeholder="输入名称" maxlength="100"')}${type==='skill'?'':field('分类目录（可选）','new-folder',folder,'placeholder="可留空"')}<p class="text-muted">${type==='character'?'在此分类内创建人物，填写资料并管理图片与声线。':'将创建一份可直接编辑和导出的 Markdown 文档。'}</p>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="create-doc">${type==='character'?'创建人物':'创建文档'}</button>`);document.querySelector('#new-title').focus();}
function showProperties(){const d=current();showModal('文档属性',`${field('名称','prop-title',d.title,'maxlength="100"')}${d.type==='skill'?'':field('分类目录','prop-folder',d.folder)}<div class="field"><label>状态</label><select id="prop-status"><option value="draft" ${d.status==='draft'?'selected':''}>草稿</option><option value="confirmed" ${d.status==='confirmed'?'selected':''}>已确认</option></select></div><div class="field"><label>稳定 ID</label><input readonly value="${e(d.id)}"><small>重命名时保留 ID，便于关联与外部 AI 操作。</small></div><div class="delete-zone"><button class="btn danger" data-action="delete-doc">移入垃圾桶</button></div>`,`<button class="btn primary" data-action="save-properties">保存属性</button>`);}
function showRefs(){const d=current();showModal('选择参考设定',`<p class="notice">勾选后，文档正文将参与提示词组装。参考图请在参考资料页单独添加，避免未经选择就发送。</p>${project.docs.filter(x=>x.id!==d.id).map(x=>`<label class="check-row"><input type="checkbox" name="reference" value="${e(x.id)}" ${(d.refs||[]).includes(x.id)?'checked':''}><span>${e(x.title)}<small>${TYPES[x.type].label} / ${e(x.folder||'未分类')} · ${x.status==='confirmed'?'已确认':'草稿'}</small></span></label>`).join('')||'<p class="text-muted">先创建其他文档，再建立参考关系。</p>'}`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-refs">应用引用</button>`);}




function makePrompt(){const d=current();const refs=referenceDocs(d,project.docs);const images=(d.images||[]).filter(r=>r.enabled!==false);d.draft||={};d.draft.prompt=buildPrompt({doc:d,refs,images,action:activeAction(),request:d.draft.request,preserve:d.draft.preserve});markDirty();render();}
function fileDialog(accept,callback,multiple=true){const input=document.querySelector('#file-input');input.value='';input.accept=accept;input.multiple=multiple;input.onchange=()=>Promise.resolve(callback([...input.files])).catch(err=>toast(err.message,true));input.click();}
async function uploadImages(files,asMedia=false){const d=current();if(asMedia&&['music','sound'].includes(d.type)&&files.some(f=>!f.type.startsWith('audio/')))throw Error('音乐与音效板块请选择音频文件');for(const f of files){if(asMedia?!/^(image|audio|video)\//.test(f.type):!/^image\/(png|jpeg|webp|gif)$/.test(f.type)){toast('不支持的文件格式：'+f.name,true);continue;}if(f.size> (asMedia?30:10)*1024*1024){toast('文件超过大小限制：'+f.name,true);continue;}const id=await addFile(f,f.name);if(asMedia){snapshot(d,'替换素材前');d.media={fileId:id,name:f.name,mime:f.type};}else{d.images||=[];d.images.push({fileId:id,name:f.name,note:'',avoid:'',enabled:true,mime:f.type});}}d.updated=Date.now();await persist();if(!asMedia)tab='refs';render();}
function snapshot(d,label='手动快照'){d.versions||=[];d.versions.push({id:uid(),time:Date.now(),label,...contentSnapshot(d)});}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制');}catch{showModal('复制内容','<p class="text-muted">插件界面未获得剪贴板权限，请手动选择下方内容。</p><textarea id="copy-fallback" class="source-editor"></textarea>');document.querySelector('#copy-fallback').value=text;document.querySelector('#copy-fallback').select();}}
function download(blob,name){if(typeof window.__NARRATIVE_DOWNLOAD__!=='function')throw Error('请从管理工坊插件保存文件');const operation=window.__NARRATIVE_DOWNLOAD__(blob,name);operation.catch(err=>toast(err.message,true));return operation;}
async function exportProject(){
  if(!await persist())return;const exportState=structuredClone(project);const docs=exportState.docs;const files=[],added=new Set();let resourceOwner=null;
  const resourcePath=(id,name)=>`资源/${id}-${safePath(name).replace(/\//g,'_')}`;
  async function addResource(r){if(!r?.fileId)return null;const legacy=resourcePath(r.fileId,r.name||'image.png');const path=resourceOwner?attachmentFolder(resourceOwner,r.mime||'')+'/'+r.fileId+'-'+safePath(r.name||'素材').replaceAll('/','_'):legacy;if(!added.has(path)){const f=await getFile(r.fileId);if(!f){toast('导出提示：缺少资源 '+(r.name||r.fileId),true);return null;}files.push({name:path,data:f.blob});added.add(path);if(!added.has(legacy)){files.push({name:legacy,data:f.blob});added.add(legacy);}}return path;}
  for(const doc of docs){resourceOwner=doc;const folder=documentFolder(doc);const path=`${folder}/${safePath(docDisplayName(doc)).replace(/\//g,'_')}-${doc.id}.md`;let md=serializeMD(doc);if(doc.details){const details=structuredClone(doc.details);for(const r of allFileReferences(details))r.path=await addResource(r);md=md.replace(/^details:.*$/m,'details: '+JSON.stringify(details));}if(doc.character){const c=structuredClone(doc.character);for(const [k,r] of Object.entries(c.files||{}))c.files[k]={...r,path:await addResource(r)};md=md.replace(/^character:.*$/m,'character: '+JSON.stringify(c));}if(doc.dialogue){const dialogue=structuredClone(doc.dialogue);for(const l of dialogue.lines||[]){if(l.audio)l.audio={...l.audio,path:await addResource(l.audio)};l.audioHistory=await Promise.all((l.audioHistory||[]).map(async a=>({...a,path:await addResource(a)})));}md=md.replace(/^dialogue:.*$/m,'dialogue: '+JSON.stringify(dialogue));}const refs=(doc.refs||[]).filter(id=>docs.some(x=>x.id===id));const imageMeta=[];
    for(const r of doc.images||[]){const resource=await addResource(r);imageMeta.push({...r,path:resource});}
    let mediaMeta=null;if(doc.media)mediaMeta={...doc.media,path:await addResource(doc.media)};
    // Structured reference metadata lives in Markdown front matter, not an opaque manifest.
    md=md.replace(/^---\n[\s\S]*?\n---/,block=>block.replace(/^references:.*$/m,`references: ${JSON.stringify(refs)}`).replace(/^reference_images:.*$/m,`reference_images: ${JSON.stringify(imageMeta)}`).replace(/^media:.*$/m,`media: ${JSON.stringify(mediaMeta)}`));
    md=md.replace(/\n<!-- workshop:attachments:start -->[\s\S]*?<!-- workshop:attachments:end -->\n?/g,'');
    if(imageMeta.length||mediaMeta?.path)md+='\n<!-- workshop:attachments:start -->\n';
    if(imageMeta.length)md+=`\n## 参考图文件\n\n${imageMeta.map(r=>`${r.path?`![${r.name.replace(/\]/g,'')}](${encodeURI('../'+r.path)})`:'图片缺失'}\n\n参考用途：${r.note||'未填写'}${r.avoid?`\n不参考：${r.avoid}`:''}`).join('\n\n')}\n`;
    if(mediaMeta?.path)md+=`\n## 素材文件\n\n[${mediaMeta.name}](${encodeURI('../'+mediaMeta.path)})\n`;
    if(imageMeta.length||mediaMeta?.path)md+='\n<!-- workshop:attachments:end -->\n';
    files.push({name:path,data:md});
    for(const v of doc.versions||[]){for(const r of allFileReferences(v.details||{}))r.path=await addResource(r);const image=v.media?await addResource(v.media):null;files.push({name:`版本/${doc.id}/${v.id}.md`,data:`---\nversion_id: ${v.id}\ndoc_id: ${doc.id}\ntime: ${v.time}\nlabel: ${JSON.stringify(v.label)}\nmedia: ${JSON.stringify(v.media?{...v.media,path:image}:null)}\ndetails: ${JSON.stringify(v.details||{})}\n---\n\n${v.md||''}`});}
  }
  resourceOwner=null;for(const task of exportState.tasks){const image=task.fileId?await addResource({fileId:task.fileId,name:task.imageName||'result.png'}):null;files.push({name:`生成记录/${task.id}.md`,data:`---\ntask_id: ${task.id}\ndoc_id: ${task.docId}\ntime: ${task.time}\nstatus: ${task.status}\nmodel: ${JSON.stringify(task.model)}\naction: ${JSON.stringify(task.action)}\ntitle: ${JSON.stringify(task.title)}\nimage: ${JSON.stringify(image)}\nfile_id: ${JSON.stringify(task.fileId||null)}\n---\n\n# 生成记录\n\n## 输入提示词\n\n${task.prompt}\n\n## 输出结果\n\n${task.result||task.error||''}`});}
  for(const entry of exportState.trash||[]){const copy=structuredClone(entry);const withPath=async r=>({...r,path:await addResource(r)});if(copy.kind==='document'){for(const r of allFileReferences(copy.data.details||{}))r.path=await addResource(r);copy.data.images=await Promise.all((copy.data.images||[]).map(withPath));if(copy.data.media)copy.data.media=await withPath(copy.data.media);for(const l of copy.data.dialogue?.lines||[]){if(l.audio)l.audio=await withPath(l.audio);l.audioHistory=await Promise.all((l.audioHistory||[]).map(withPath));}for(const [key,r] of Object.entries(copy.data.character?.files||{}))copy.data.character.files[key]=await withPath(r);}else if(copy.kind==='reference-image')copy.data=await withPath(copy.data);else if(copy.kind==='dialogue-line'){if(copy.data.audio)copy.data.audio=await withPath(copy.data.audio);copy.data.audioHistory=await Promise.all((copy.data.audioHistory||[]).map(withPath));}files.push({name:'垃圾桶/'+copy.id+'.md',data:'---\ntrash_entry: '+JSON.stringify(copy)+'\n---\n\n# 垃圾桶资料\n\n'+(copy.title||'未命名')});}
  const backup=backupState(exportState);resourceOwner=null;for(const r of allFileReferences(backup)){r.path=await addResource(r);if(!r.path)throw Error('备份缺少文件：'+(r.name||r.fileId));}files.push({name:'完整备份.md',data:'---\nbackup_project: '+JSON.stringify(backup)+'\n---\n\n# 完整项目备份\n'});files.push({name:OVERVIEW_FILE,data:buildProjectOverview(exportState)});
  files.push({name:'项目说明.md',data:`---\nproject_id: ${exportState.id}\nname: ${JSON.stringify(exportState.name)}\ndescription: ${JSON.stringify(exportState.description||'')}\ncontent_tables: ${JSON.stringify(exportState.contentTables||{})}\ncontent_number_counters: ${JSON.stringify(exportState.contentNumberCounters||{})}\nitem_settings: ${JSON.stringify(exportState.itemSettings||{})}\nskill_settings: ${JSON.stringify(skillSettings(exportState))}\nformat: narrative-workshop-v1\n---\n\n# ${exportState.name}\n\n${exportState.description||''}\n\n本包包含 Markdown 正式资料与附件，生成记录不含 API 密钥。\n修改时保留文档 ID、类型与引用字段。文件重命名不应更改 ID。\n\n## 文档索引\n\n${files.filter(f=>f.name.endsWith('.md')&&!f.name.startsWith('版本/')&&!f.name.startsWith('生成记录/')).map(f=>`- [${f.name}](${encodeURI(f.name)})`).join('\n')}`});
  
  const zipBytes=22+files.reduce((n,f)=>n+76+2*new TextEncoder().encode(f.name).length+(typeof f.data==='string'?new TextEncoder().encode(f.data).length:f.data.size),0);
  if(files.length>2000||zipBytes>100*1024*1024)throw Error('项目超过 ZIP 备份容量，请使用“本地完整备份”，可保留全部素材与历史。');
  await download(await createZIP(files),safePath(exportState.name)+'-项目备份.zip');toast('项目已导出，包含资料、素材与版本记录');
}

async function saveToDisk(){if(savingToDisk)return;savingToDisk=true;try{if(await persist())toast('已保存到本地项目目录');}finally{savingToDisk=false;}}
function deletedProjectIDs(){return new Set();}
function markProjectDeleted(){}
async function showDeleteProject(id){if(busy||savingToDisk)throw Error('请等待当前任务完成');const target=projects.find(p=>p.id===id);if(!target)return;try{if(!await persist())return;target.deleted=true;target.deletedAt=Date.now();await putProject(target);markProjectDeleted(target.id,true);projects=projects.filter(p=>p.id!==target.id);if(project.id===target.id){project=projects[0];if(!project){closeModal();showProjectOnboarding();return;}localStorage.setItem('nw-active',project.id);type='script';selected=null;special=null;tab='preview';query='';restoreNavigation();await warmFiles();}closeModal();render();toast('项目已移入回收站，可恢复');}catch(err){toast(err.message,true);}}
async function showProjectTrash(){const items=(await transaction('projects','readonly',store=>store.getAll())).filter(p=>p.deleted||deletedProjectIDs().has(p.id));showModal('项目回收站',items.map(p=>'<div class="project-row"><div><strong>'+e(p.name)+'</strong><small>'+p.docs.length+' 份文档</small></div><button class="btn" data-restore-deleted="'+e(p.id)+'">恢复项目</button></div>').join('')||'<p class="text-muted">回收站为空。</p>');for(const button of modal.querySelectorAll('[data-restore-deleted]'))button.onclick=async()=>{try{const target=items.find(p=>p.id===button.dataset.restoreDeleted);target.deleted=false;target.archived=false;target.legacyRestored=true;await putProject(target);markProjectDeleted(target.id,false);if(!projects.some(p=>p.id===target.id))projects.push(target);closeModal();toast('项目已恢复，可从项目列表打开');}catch(err){toast(err.message,true);}};}

function jsonField(value,fallback){try{return JSON.parse(value);}catch{return fallback;}}
async function importFiles(files){
  if(files.length===1&&files[0].name.toLowerCase().endsWith('.zip')){const entries=await readZIP(files[0]);await importArchive(entries);return;}
  const mds=files.filter(f=>f.name.toLowerCase().endsWith('.md'));if(!mds.length)throw Error('请选择 MD 文档或本工具导出的 ZIP');
  const pending=[];for(const file of mds){const md=await file.text(),p=parseMD(md);const t=TYPES[p.meta.type]?p.meta.type:type;const id=p.meta.id||uid();pending.push({id,type:t,contentNumber:p.meta.content_number||undefined,title:jsonField(p.meta.title,p.title||file.name.replace(/\.md$/i,'')),folder:jsonField(p.meta.folder,'导入资料'),status:p.meta.status==='confirmed'?'confirmed':'draft',md,details:jsonField(p.meta.details,{}),character:jsonField(p.meta.character,null),dialogue:jsonField(p.meta.dialogue,null),participants:jsonField(p.meta.participants,[]),refs:jsonField(p.meta.references,[]),images:jsonField(p.meta.reference_images,[]),versions:[],updated:Date.now()});}
  const conflicts=pending.filter(d=>project.docs.some(x=>x.id===d.id));showModal('确认导入 Markdown',`<p class="notice">${pending.length} 份文档，其中 ${conflicts.length} 份与现有 ID 相同。选择更新时会先保存旧版快照。单独 MD 引用的图片需要另外添加。</p>${pending.map(d=>`<div class="related-row"><span>${e(d.title)}</span><small>${project.docs.some(x=>x.id===d.id)?'更新现有文档':'新建文档'}</small></div>`).join('')}`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="confirm-md-import">确认导入</button>`);
  document.querySelector('#confirm-md-import').onclick=async()=>{for(const d of pending){const old=project.docs.find(x=>x.id===d.id);if(old){snapshot(old,'导入更新前');Object.assign(old,{...d,versions:old.versions,images:old.images,media:old.media});}else project.docs.push(d);}selected=pending[0].id;type=pending[0].type;special=null;tab='preview';await warmFiles();await persist();closeModal();render();toast('文档已导入');};
}
async function importArchive(entries){
  if(busy)throw Error('请等待当前 AI 任务完成后导入项目');
  const decoder=new TextDecoder(),index=entries.find(f=>f.name==='项目说明.md');if(!index)throw Error('未找到项目说明.md，请导入本工具导出的项目包');const header=parseMD(decoder.decode(index.data));if(header.meta.format!=='narrative-workshop-v1')throw Error('暂不支持此项目包格式');
  let backupProject=null;const docs=[],versions=[],tasks=[],trash=[];for(const f of entries.filter(f=>f.name.endsWith('.md')&&f.name!=='项目说明.md')){const md=decoder.decode(f.data),p=parseMD(md);if(p.meta.backup_project){backupProject=jsonField(p.meta.backup_project,null);continue;}if(p.meta.trash_entry){const entry=jsonField(p.meta.trash_entry,null);if(entry)trash.push(entry);continue;}if(p.meta.version_id){versions.push({id:p.meta.version_id,docId:p.meta.doc_id,time:Number(p.meta.time),label:jsonField(p.meta.label,'历史版本'),md:p.body,details:jsonField(p.meta.details,{}),media:jsonField(p.meta.media,null)});continue;}if(p.meta.task_id){const parts=p.body.split('\n## 输出结果\n\n');tasks.push({id:p.meta.task_id,docId:p.meta.doc_id,time:Number(p.meta.time),status:p.meta.status==='running'?'cancelled':p.meta.status,model:jsonField(p.meta.model,p.meta.model),action:jsonField(p.meta.action,'生成'),title:jsonField(p.meta.title,'任务'),prompt:parts[0].split('## 输入提示词\n\n').slice(1).join('## 输入提示词\n\n'),result:parts.slice(1).join('\n## 输出结果\n\n'),fileId:jsonField(p.meta.file_id,null),image:jsonField(p.meta.image,null)});continue;}if(!p.meta.id)continue;const t=TYPES[p.meta.type]?p.meta.type:'script';docs.push({id:p.meta.id,type:t,contentNumber:p.meta.content_number||undefined,title:jsonField(p.meta.title,p.title),folder:jsonField(p.meta.folder,''),status:p.meta.status==='confirmed'?'confirmed':'draft',md,details:jsonField(p.meta.details,{}),character:jsonField(p.meta.character,null),dialogue:jsonField(p.meta.dialogue,null),participants:jsonField(p.meta.participants,[]),refs:jsonField(p.meta.references,[]),images:jsonField(p.meta.reference_images,[]),media:jsonField(p.meta.media,null),versions:[],updated:Date.now()});}
  if(!docs.length&&!trash.length)throw Error('项目包中没有可导入的资料');if(new Set(docs.map(d=>d.id)).size!==docs.length)throw Error('项目包含重复文档 ID，请先修复');
  showModal('导入项目副本',`<p class="notice">将创建独立项目，不覆盖当前项目。</p><div class="related-row"><span>${e(jsonField(header.meta.name,'导入项目'))}</span><small>${docs.length} 份文档 · ${entries.filter(f=>!f.name.endsWith('.md')).length} 个资源</small></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="confirm-zip-import">导入并打开</button>`);
  document.querySelector('#confirm-zip-import').onclick=async()=>{try{if(backupProject){const restored=await restoreBackupState(backupProject,entries,addFile);restored.name=(restored.name||'导入项目')+' · 导入';if(!await persist())return;const imported=await nativeStore.importProject(restored,nativeStore.defaultDirectory);projects.push(imported);project=imported;selected=project.docs[0]?.id||null;type=project.docs[0]?.type||'script';tab='preview';special=null;localStorage.setItem('nw-active',project.id);await warmFiles();closeModal();render();toast('完整备份已恢复到新的项目目录');return;}if(backupProject){docs.splice(0,docs.length,...backupProject.docs);tasks.splice(0,tasks.length,...(backupProject.tasks||[]));trash.splice(0,trash.length,...(backupProject.trash||[]));}const idMap=new Map(),oldFileIds=new Map();const restoreResource=async(r)=>{if(!r?.path)return r;const file=entries.find(f=>f.name===r.path);if(!file){r.fileId='missing-'+uid();return r;}if(!idMap.has(r.path)){const extension=r.path.split('.').pop().toLowerCase();const mime=r.mime||({'png':'image/png','jpg':'image/jpeg','jpeg':'image/jpeg','webp':'image/webp','gif':'image/gif','mp3':'audio/mpeg','wav':'audio/wav','ogg':'audio/ogg','flac':'audio/flac','m4a':'audio/mp4','mp4':'video/mp4'})[extension]||'application/octet-stream';idMap.set(r.path,await addFile(new Blob([file.data],{type:mime}),r.name||r.path.split('/').pop()));}if(r.fileId)oldFileIds.set(r.fileId,idMap.get(r.path));return {...r,fileId:idMap.get(r.path),mime:r.mime||({'png':'image/png','jpg':'image/jpeg','webp':'image/webp','wav':'audio/wav','ogg':'audio/ogg','mp3':'audio/mpeg'}[r.path.split('.').pop().toLowerCase()]||'application/octet-stream')};};
    for(const d of docs){if(d.character?.files)for(const [k,r] of Object.entries(d.character.files))d.character.files[k]=await restoreResource(r);d.images=await Promise.all(d.images.map(restoreResource));if(d.media)d.media=await restoreResource(d.media);for(const v of versions.filter(v=>v.docId===d.id)){if(v.media)v.media=await restoreResource(v.media);d.versions.push({...v,...(v.media?{fileId:v.media.fileId}:{})});}}
    for(const doc of docs){for(const line of doc.dialogue?.lines||[]){if(line.audio)line.audio=await restoreResource(line.audio);line.audioHistory=await Promise.all((line.audioHistory||[]).map(restoreResource));}}for(const t of tasks){if(t.image){const r=await restoreResource({path:t.image,name:t.image.split('/').pop()});t.fileId=r.fileId;}}
    for(const entry of trash){if(entry.kind==='document'){entry.data.images=await Promise.all((entry.data.images||[]).map(restoreResource));if(entry.data.media)entry.data.media=await restoreResource(entry.data.media);for(const l of entry.data.dialogue?.lines||[]){if(l.audio)l.audio=await restoreResource(l.audio);l.audioHistory=await Promise.all((l.audioHistory||[]).map(restoreResource));}for(const [key,r] of Object.entries(entry.data.character?.files||{}))entry.data.character.files[key]=await restoreResource(r);}else if(entry.kind==='reference-image')entry.data=await restoreResource(entry.data);else if(entry.kind==='dialogue-line'){if(entry.data.audio)entry.data.audio=await restoreResource(entry.data.audio);entry.data.audioHistory=await Promise.all((entry.data.audioHistory||[]).map(restoreResource));}}
    for(const doc of docs){for(const r of allFileReferences(doc.details||{}))Object.assign(r,await restoreResource(r));}for(const entry of trash)if(entry.kind==='document')for(const r of allFileReferences(entry.data.details||{}))Object.assign(r,await restoreResource(r));
    if(backupProject)for(const r of allFileReferences({docs,trash,tasks}))Object.assign(r,await restoreResource(r));
    const remapReviews=value=>{if(!value||typeof value!=='object')return;if(value.reviewOriginalId&&oldFileIds.has(value.reviewOriginalId))value.reviewOriginalId=oldFileIds.get(value.reviewOriginalId);for(const child of Object.values(value))if(child&&typeof child==='object')remapReviews(child);};remapReviews(docs);remapReviews(trash);for(const doc of docs)remapDialogueReferences(doc,oldFileIds);for(const entry of trash){if(entry.kind==='document')remapDialogueReferences(entry.data,oldFileIds);else if(entry.kind==='dialogue-line')remapDialogueReferences({dialogue:{lines:[entry.data]}},oldFileIds);}await persist();const next={...(backupProject||{}),id:uid(),name:jsonField(header.meta.name,'导入项目')+' · 导入',description:jsonField(header.meta.description,''),contentTables:jsonField(header.meta.content_tables,{}),contentNumberCounters:jsonField(header.meta.content_number_counters,{}),itemSettings:jsonField(header.meta.item_settings,{}),skillSettings:jsonField(header.meta.skill_settings,{}),docs,tasks,trash,contentTemplatesInitialized:true,created:Date.now()};const imported=await nativeStore.importProject(next,nativeStore.defaultDirectory);Object.assign(next,imported);projects.push(next);project=next;localStorage.setItem('nw-active',project.id);type=docs[0]?.type||'script';selected=docs[0]?.id||null;special=null;tab='preview';closeModal();render();toast('项目副本已导入');}catch(err){toast('导入失败：'+err.message,true);}};
}

async function blobDataURL(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}
async function getImageInputs(d){const list=[];if(d.media?.mime?.startsWith('image/'))list.push({...d.media,note:'当前要修改的原图'});list.push(...(d.images||[]).filter(r=>r.enabled!==false));const unique=[...new Map(list.map(r=>[r.fileId,r])).values()];const result=[];for(const r of unique){const f=await getFile(r.fileId);if(!f)throw Error('参考图片缺失：'+r.name);result.push({...r,blob:f.blob});}return result;}


async function runAI(){const d=current();makePrompt();await submitGPT(d,d.draft.prompt);}
async function adoptTask(id){const task=project.tasks.find(t=>t.id===id),d=project.docs.find(d=>d.id===task?.docId);if(!d)throw Error('原内容已不存在');if(task.status!=='done')return;if(task.result){showModal('确认采纳候选稿',`<p class="notice">将更新「${e(d.title)}」的${CONTENT_FIELDS[d.type]?'补充说明':'正文'}，旧资料会保留为版本快照。请先核对设定是否正确。</p><details><summary>当前正文</summary><div class="document">${markdown(d.md)}</div></details><hr><div class="document">${markdown(task.result)}</div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="confirm-adopt">采纳并保留旧版</button>`);document.querySelector('#confirm-adopt').onclick=async()=>{snapshot(d,'AI 采纳前');if(CONTENT_FIELDS[d.type]){d.details||={};d.details.notes=task.result;}else d.md=task.result;d.updated=Date.now();task.status='adopted';await persist();closeModal();render();toast('候选稿已采纳，旧版保留在版本记录中');};}
  else if(task.fileId){const asset={id:uid(),type:'asset',title:d.title+' · '+task.action,folder:TYPES[d.type].label,status:'draft',md:template('asset',d.title+' · '+task.action),refs:[d.id],images:[],versions:[],media:{fileId:task.fileId,name:task.imageName,mime:'image/png'},updated:Date.now()};project.docs.push(asset);task.status='adopted';await persist();selected=asset.id;type='asset';special=null;tab='preview';render();toast('已保存到素材库，并关联原内容');}}

async function action(name,el){
  const d=current();if(savingToDisk&&['import','switch-project','create-project','delete-project'].includes(name))throw Error('请等待保存完成');switch(name){
    case 'type': linkedDocId='';delete galleryFilters.docId;type=el.dataset.type;special=null;query='';selected=project.docs.find(x=>x.id===selected&&x.type===type)?.id||project.docs.find(x=>x.type===type)?.id;tab=el.dataset.mode||'preview';mobileOpen=false;render();break;
    case 'select':{const next=project.docs.find(x=>x.id===el.dataset.id);if(!next)return;const sameType=type===next.type;selected=next.id;type=next.type;special=null;if(!sameType)tab=WORKFLOW.find(v=>v[0]===type)?.[1]||'preview';mobileOpen=false;render();break;}
    case 'tab':tab=el.dataset.tab;render();break;
    case 'page':special=el.dataset.page;mobileOpen=false;render();break;
    case 'mobile':mobileOpen=!mobileOpen;document.querySelector('.directory').classList.toggle('visible',mobileOpen);break;
    case 'toggle-folder':{const folder=el.nextElementSibling;folder.hidden=!folder.hidden;break;}
    case 'new':showNew();break;
    case 'new-in-folder':showNew(el.dataset.folder);break;
    case 'folder':showModal('新建分类与文档',`${field('分类名称','folder-name','','placeholder="例如：地理与环境"')}<p class="text-muted">创建分类后添加第一份文档。目录由文档的分类字段组织。</p>`,`<button class="btn primary" id="next-folder">下一步</button>`);document.querySelector('#next-folder').onclick=()=>{const name=document.querySelector('#folder-name').value.trim()||'未分类';showNew(name);};break;
    case 'create-doc':{const title=document.querySelector('#new-title').value.trim()||'未命名'+TYPES[type].label,folder=document.querySelector('#new-folder')?.value.trim()||'';const doc={id:uid(),type,title,folder,status:'draft',md:template(type,title),refs:[],images:[],versions:[],updated:Date.now()};if(aggregateType(type))doc.details={tableId:activeTable()};if(type==='character')doc.character={name:document.querySelector('#new-title').value.trim()};project.docs.push(doc);selected=doc.id;special=null;tab='preview';await persist();closeModal();render();toast(aggregateType(type)?'已添加到当前表':type==='character'?'已在'+folder+'中创建人物':'已创建策划条目');break;}
    case 'close-modal':closeModal();break;
    case 'properties':showProperties();break;
    case 'save-properties':{const title=document.querySelector('#prop-title').value.trim()||'未命名'+TYPES[d.type].label;d.title=title;d.folder=d.type==='skill'?'':document.querySelector('#prop-folder').value.trim();d.status=document.querySelector('#prop-status').value;d.updated=Date.now();await persist();closeModal();render();break;}
    case 'delete-doc':showDeleteDocument(d);break;
    case 'choose-participants':showParticipants();break;
    case 'save-participants':d.participants=[...modal.querySelectorAll('[name=participant]:checked')].map(x=>x.value);d.updated=Date.now();if(d.draft)delete d.draft.prompt;await persist();closeModal();render();toast('主要参与人物已更新');break;
    case 'choose-refs':showRefs();break;
    case 'save-refs':d.refs=[...modal.querySelectorAll('input[name="reference"]:checked')].map(x=>x.value);d.updated=Date.now();await persist();closeModal();render();break;
    case 'remove-ref':d.refs=(d.refs||[]).filter(id=>id!==el.dataset.id);d.participants=(d.participants||[]).filter(id=>id!==el.dataset.id);await persist();render();break;
    case 'upload-ref':fileDialog('image/png,image/jpeg,image/webp,image/gif',files=>uploadImages(files));break;
    case 'upload-media':fileDialog(['music','sound'].includes(d.type)?'audio/*':'image/*,audio/*,video/*',files=>uploadImages(files,true),false);break;
    case 'remove-image':recycle(project,'reference-image',d.images[Number(el.dataset.index)],{docId:d.id,index:Number(el.dataset.index),title:d.images[Number(el.dataset.index)].name});d.images.splice(Number(el.dataset.index),1);await persist();render();break;
    case 'library-ref':{const assets=project.docs.filter(x=>x.media?.mime?.startsWith('image/'));showModal('从素材库添加参考',assets.map(x=>`<label class="check-row"><input name="library-image" type="checkbox" value="${e(x.id)}"><span>${e(x.title)}</span></label>`).join('')||'<p class="text-muted">素材库还没有图片。可先上传图片到素材条目。</p>',`<button class="btn primary" id="add-library">添加所选</button>`);document.querySelector('#add-library').onclick=async()=>{const ids=[...modal.querySelectorAll('[name="library-image"]:checked')].map(x=>x.value);d.images||=[];for(const id of ids){const asset=assets.find(x=>x.id===id);if(!d.images.some(r=>r.fileId===asset.media.fileId))d.images.push({...asset.media,note:'',avoid:'',enabled:true});}await persist();closeModal();render();};break;}
    case 'zoom':{const src=objectURLs.get(el.dataset.file);if(!src)return toast('图片文件不存在',true);showModal('图片预览',`<div style="text-align:center"><img class="zoom-image" src="${src}" alt="参考图大图"></div>`);break;}
    case 'operation':setDraft('action',el.dataset.op);render();break;
    case 'collapse-composer':{const body=document.querySelector('.composer-body');body.hidden=!body.hidden;break;}
    case 'copy-md':await copy(serializeMD(d));break;
    case 'download-md':download(new Blob([serializeMD(d)],{type:'text/markdown;charset=utf-8'}),safePath(d.title)+'.md');break;
    case 'download-media':{const f=await getFile(d.media.fileId);if(f)download(f.blob,d.media.name);break;}
    case 'snapshot':snapshot(d);await persist();if(tab==='history')render();toast('已保存内容快照');break;
    case 'version-source':{const v=d.versions.find(v=>v.id===el.dataset.version);showModal('历史内容',`<pre>${e(v.md)}</pre>`);break;}
    case 'restore':{const v=d.versions.find(v=>v.id===el.dataset.version);if(!v)return;snapshot(d,'恢复版本前');restoreSnapshot(d,v);d.updated=Date.now();await persist();tab='preview';render();toast('已恢复版本，恢复前内容也已保留');break;}
    case 'media-api':showMediaAPI(el.dataset.kind);break;
    case 'save-media-api':saveMediaAPI();closeModal();render();toast('配置已保存');break;
    case 'test-media-api':await testMediaAPI();break;
    case 'run-ai':await runAI();break;
    case 'confirm-run':await runAI();break;
    case 'cancel-ai':controller?.abort();break;
    case 'adopt':await adoptTask(el.dataset.task);break;
    case 'continue-task':{const t=project.tasks.find(t=>t.id===el.dataset.task),doc=project.docs.find(x=>x.id===t.docId);if(!doc)throw Error('原内容已不存在');selected=doc.id;type=doc.type;special=null;doc.draft||={};doc.draft.prompt=t.prompt+'\n\n## 上次候选结果\n'+(t.result||'请参考上次生成图片继续调整。');if(t.fileId){doc.images||=[];if(!doc.images.some(r=>r.fileId===t.fileId))doc.images.push({fileId:t.fileId,name:'上次生成结果',note:'基于此候选图继续修改',enabled:true,mime:'image/png'});}tab='history';await persist();render();toast('已将候选内容加入下一次修改，请补充新要求');break;}
    case 'task-input':{const t=project.tasks.find(t=>t.id===el.dataset.task);showModal('生成任务输入',`<p class="text-muted">${e(t.model)} · ${e(t.base||'')}<br>实际图片：${(t.inputImages||[]).map(x=>e(x.name)).join('、')||'无'}</p><pre>${e(t.prompt)}</pre>`);break;}
    case 'export-overview':await persist();download(new Blob([buildProjectOverview(project)],{type:'text/markdown;charset=utf-8'}),OVERVIEW_FILE);toast('全量资料已导出，图片和音频请随项目包一并提供');break;
    case 'export':await exportProject();break;
    case 'reference-export':await exportProject(true);break;
    case 'import':fileDialog('.md,.zip',importFiles);break;
    case 'save-disk':await saveToDisk();break;
    case 'delete-project':showDeleteProject(el.dataset.project);break;
    case 'project-trash':closeModal();await openRecycleBin();break;
    case 'open-trash':await openRecycleBin();break;
    case 'restore-trash':await restoreTrashUI(el);break;
    case 'purge-trash':confirmPurgeTrash(el);break;
    case 'projects':showModal('项目工作空间',`${projects.map(p=>`<div class="project-row"><div><strong>${e(p.name)}</strong><small>${p.docs.length} 份文档${p.id===project.id?' · 当前项目':''}</small></div><div style="display:flex;gap:8px"><button class="btn" data-action="switch-project" data-project="${e(p.id)}">打开</button><button class="btn danger" data-action="delete-project" data-project="${e(p.id)}">删除</button></div></div>`).join('')}<div style="margin-top:20px">${field('新项目名称','new-project-name','','placeholder="例如：我的第一款游戏"')}${field('保存位置','new-project-directory',nativeStore.defaultDirectory||'','placeholder="填写保存目录完整路径"')}</div>`,`<button class="btn" data-action="project-trash">项目回收站</button><button class="btn" data-action="close-modal">关闭</button><button class="btn primary" data-action="create-project">${icon('plus')}新建项目</button>`);break;
    case 'create-project':{if(busy||savingToDisk)throw Error('请等待当前任务或保存完成后切换项目');const name=document.querySelector('#new-project-name').value.trim(),directory=document.querySelector('#new-project-directory').value.trim();if(!name||!directory)throw Error('请填写项目名称和保存位置');if(!await persist())return;const p=await nativeStore.createProject(name,directory);projects.push(p);project=p;localStorage.setItem('nw-active',p.id);type='script';selected=null;special=null;tab='preview';closeModal();render();toast('项目已创建并保存到本地目录');break;}
    case 'switch-project':{gallerySelection.clear();audioSelection.clear();if(busy)throw Error('请等待当前 AI 任务完成后切换项目');if(!await persist())return;project=projects.find(p=>p.id===el.dataset.project);localStorage.setItem('nw-active',project.id);type='script';selected=project.docs[0]?.id;if(selected)type=project.docs[0].type;special=null;tab='preview';restoreNavigation();await warmFiles();closeModal();render();break;}
    case 'save-project':{const name=document.querySelector('#project-name').value.trim()||'未命名项目';project.name=name;project.description=document.querySelector('#project-description').value.trim();await persist();render();toast('项目信息已保存');break;}
    case 'archived-projects':showModal('历史项目备份',archivedProjects.map(p=>'<div class="project-row"><div><strong>'+e(p.name)+'</strong><small>'+p.docs.length+' 份文档 · 已归档</small></div><button class="btn" data-action="restore-project" data-project="'+e(p.id)+'">恢复到项目列表</button></div>').join('')||'<p class="text-muted">暂无历史项目。</p>');break;
    case 'restore-project':{const p=archivedProjects.find(p=>p.id===el.dataset.project);if(!p)return;p.archived=false;p.legacyRestored=true;await putProject(p);projects.push(p);archivedProjects=archivedProjects.filter(x=>x.id!==p.id);closeModal();toast('历史项目已恢复，可从项目列表打开');break;}
    case 'help':showModal('欢迎来到管理工坊',`<p class="notice">每个板块预置一份待填写的默认文档，不包含案例内容。可以直接编辑，也可新建自己的设定。</p><div class="document"><h2>开始创作</h2><p>1. 左侧切换板块，在目录上方点击 + 新建内容。</p><p>2. 在中间填写策划字段，所有字段均可留空。</p><p>3. 在「参考资料」关联文档、上传图片并填写参考用途。</p><p>4. 在当前 GPT 对话中描述要求，生成文字或图片并保存回项目。</p><p>5. 在版本记录中确认候选，导出项目 ZIP 作为备份。</p><h2>当前版本边界</h2><p>资料以 MD 和附件保存在本机。AI 请求由插件处理，配音使用本地 IndexTTS 2.5。团队实时同步和引擎专用插件尚未接入。</p></div>`);break;
  }
}
document.addEventListener('click',ev=>{const target=ev.target.closest('[data-action]');if(target&&!target.disabled)Promise.resolve(action(target.dataset.action,target)).catch(err=>toast(err.message,true));});
document.addEventListener('input',ev=>{const el=ev.target,d=current();if(el.id==='search'){query=el.value;rememberNavigation();const old=document.querySelector('.directory-scroll');const templateEl=document.createElement('div');templateEl.innerHTML=renderDirectory();old.replaceWith(templateEl.querySelector('.directory-scroll'));document.querySelector('.directory-tools').replaceWith(templateEl.querySelector('.directory-tools'));if(['item','skill','term'].includes(type))document.querySelector('.workspace').innerHTML=renderWorkspace();return;}if(!d)return;
  if(el.dataset.charField){d.character||={};d.character[el.dataset.charField]=el.value;if(el.dataset.charField==='name'){d.title=el.value.trim()||'未命名人物';const heading=document.querySelector('.character-title');if(heading)heading.textContent=d.title;for(const item of document.querySelectorAll('.directory [data-action="select"]')){if(item.dataset.id===d.id){const label=item.querySelector('strong');if(label)label.textContent=d.title;}}for(const button of document.querySelectorAll('[data-move-character],[data-delete-character],[data-character-properties]')){if(button.dataset.characterProperties===d.id)button.setAttribute('aria-label','属性配置：'+d.title);if(button.dataset.moveCharacter===d.id)button.setAttribute('aria-label','移动人物：'+d.title);if(button.dataset.deleteCharacter===d.id)button.setAttribute('aria-label','删除人物：'+d.title);}}d.updated=Date.now();markDirty();}
  if(el.dataset.contentField){d.details||={};d.details[el.dataset.contentField]=el.value;d.status='draft';d.updated=Date.now();markDirty();}
  if(el.id==='request')setDraft('request',el.value);if(el.id==='preserve')setDraft('preserve',el.value);if(el.id==='final-prompt')setDraft('prompt',el.value);
  if(el.dataset.refNote!==undefined){d.images[Number(el.dataset.refNote)].note=el.value;markDirty();}if(el.dataset.refAvoid!==undefined){d.images[Number(el.dataset.refAvoid)].avoid=el.value;markDirty();}
});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.refEnabled!==undefined){current().images[Number(el.dataset.refEnabled)].enabled=el.checked;markDirty();}});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key==='s'){ev.preventDefault();saveToDisk().catch(err=>toast(err.message,true));}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&project)persist();});
window.addEventListener('beforeunload',ev=>{if(saveTimer||busy){ev.preventDefault();ev.returnValue='';}});
modal.addEventListener('click',ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeModal();}});
async function init(){try{nativeStore=await connectLocalWorkspace();projects=await transaction('projects','readonly',s=>s.getAll());if(!localStorage.getItem('nw-empty-start-v1')){for(const p of projects){p.archived=true;await putProject(p);}localStorage.setItem('nw-empty-start-v1','1');}for(const p of projects){if(p.name.startsWith('雾海纪行')&&p.docs.some(d=>d.id==='world')&&!p.legacyRestored){p.archived=true;await putProject(p);}}archivedProjects=projects.filter(p=>p.archived);projects=projects.filter(p=>!p.archived&&!p.deleted&&!deletedProjectIDs().has(p.id));if(!projects.length){showProjectOnboarding();return;}const savedView=readView(sessionStorage,'nw-current-view')||readView(localStorage,'nw-last-view');project=projects.find(p=>!p.deleted&&p.id===savedView?.projectId)||projects.find(p=>p.id===localStorage.getItem('nw-active'))||projects[0];localStorage.setItem('nw-active',project.id);for(const p of projects){let migrated=ensureContentNumbers(p);for(const d of p.docs){if(d.type==='character'&&d.character){const next=normalizeCharacterFields(d.character);if(JSON.stringify(next)!==JSON.stringify(d.character)){d.character=next;migrated=true;}}if(d.type==='character'&&!CHARACTER_FOLDERS.includes(d.folder)){d.folder='其他';migrated=true;}}if(p.folders?.character){p.folders.character=[];migrated=true;}if(migrated)await putProject(p);if(initializeDefaults(p))await putProject(p);if(lockProjectDefaults(p))await putProject(p);p.tasks||=[];for(const t of p.tasks)if(t.status==='running'){t.status='cancelled';t.error='页面重新打开，未完成的请求已中断。';}}selected=project.docs.find(d=>d.type==='script')?.id||project.docs[0]?.id;if(selected)type=project.docs.find(d=>d.id===selected).type;restoreNavigation(savedView?.projectId===project.id?savedView:null);await warmFiles();if(special==='trash'){const stored=await transaction('projects','readonly',s=>s.getAll());trashOwners=stored.map(p=>projects.find(x=>x.id===p.id)||archivedProjects.find(x=>x.id===p.id)||p);}render();}catch(err){app.innerHTML=`<div class="empty"><h3>无法打开本地存储</h3><p>${e(err.message)}<br>请在 ChatGPT 桌面版启用管理工坊插件后重新打开。</p></div>`;}}


const CHARACTER_EMOTIONS=['正常','开心','生气','悲伤','恐惧','惊讶','厌恶','疑惑','害羞','傲慢','疲惫','兴奋','无奈','内疚','疯狂'];
let voicePending=false;
let characterImagePending=null;
function renderCharacter(d){if(tab==='character-properties')return renderCharacterProperties(d);const c=normalizeCharacterFields(d.character||{}),files=c.files||{},expressions=[...CHARACTER_EMOTIONS,...(c.expressions||[])];
 const input=(label,key,value)=>`<label class="char-field">${label}<input data-char-field="${key}" value="${e(value||'')}" placeholder="填写${label}"></label>`;
 const slot=(key,label,audio=false)=>{const r=audio?files[key]:displayedImage(files,key),url=r&&objectURLs.get(r.fileId),pending=!audio&&(!r||!r.confirmedAt),working=characterImagePending?.docId===d.id&&characterImagePending?.key===key;
 return `<div class="char-slot"><div class="char-image-heading"><strong>${label}</strong>${!audio?`<span class="char-image-status ${pending?'pending':'confirmed'}">${pending?'待修改':'确认'}</span>`:''}</div>${url?(audio?`<audio controls preload="none" src="${url}"></audio>`:`<img src="${url}" alt="${label}${pending?'候选图片':''}" data-action="zoom" data-file="${e(r.fileId)}">`):`<div class="char-placeholder">${icon(audio?'sound':'image')}<span>${working?'正在生成…':'尚未添加'+(audio?'声音':'图片')}</span></div>`}${!audio&&files[candidateKey(key)]&&files[key]?'<small class="text-muted">正在预览候选图，原正式图片已保留</small>':''}<button class="btn" data-char-upload="${key}" data-audio="${audio}" ${working?'disabled':''}>${icon('upload')}${r?'替换':'上传'}${audio?'音频':'图片'}</button>${r?`<button class="btn subtle" data-char-download="${key}">下载</button>`:''}${!audio?`<div class="char-image-actions"><button class="btn" data-char-image-ai="${e(key)}" data-label="${e(label)}" ${busy?'disabled':''}>${icon('spark')}${working?'生成中…':r?'AI 修改':'AI 作图'}</button><button class="btn primary" data-char-image-confirm="${e(key)}" ${!r||working||!pending?'disabled':''}>${icon('check')}确认</button></div>${working?'<button class="btn subtle" data-action="cancel-ai">取消生成</button>':''}`:''}${audio&&r&&key!=='reference'?`<button class="btn" data-char-confirm-voice="${e(key)}">${r.status==='confirmed'?'声线已确认':'确认声线'}</button>`:''}${audio&&key==='reference'?'<button class="btn primary" data-voice-record>直接录音</button>':''}${audio&&key!=='reference'?`<button class="btn primary" data-char-generate="${label}" ${voicePending?'disabled':''}>${voicePending?'生成中…':'生成声线'}</button>`:''}</div>`;};
 return `<div class="wide-page character-page"><div class="eyebrow">人物工作台</div><h1 class="character-title">${e(docDisplayName(d))}</h1><p class="panel-desc">人物资料、三视图、表情与声线 · 所有内容可选填 · 自动保存</p><section class="char-panel"><div class="char-section-heading"><h2>基本资料 <span class="char-image-status ${d.status==='confirmed'?'confirmed':'pending'}" data-character-status-label>${d.status==='confirmed'?'已确认':'待修改'}</span></h2><div class="character-basic-actions"><button class="btn" data-character-profile-status="draft" aria-pressed="${d.status!=='confirmed'}">待修改</button><button class="btn" data-character-profile-status="confirmed" aria-pressed="${d.status==='confirmed'}">确认</button>${c.profileCandidate?`<button class="btn" data-character-profile-review>查看生成结果</button>`:''}<button class="btn primary" data-character-profile-ai ${busy?'disabled':''}>${icon('spark')}AI 一键生成</button><button class="btn subtle" data-character-field-add>${icon('plus')}添加自定义字段</button></div></div><div class="character-basic-layout"><div class="character-main-image">${slot('portrait','正式主图')}${slot('design','人物设计稿')}</div><div class="char-fields">${input('姓名','name',c.name)}<label class="char-field">所属分类<select data-char-folder><option value="">未分类（可留空）</option>${CHARACTER_FOLDERS.map(x=>`<option ${d.folder===x?'selected':''}>${x}</option>`).join('')}</select></label>${input('性别','gender',c.gender)}<label class="char-field">派系<input data-char-field="faction" list="character-factions" value="${e(c.faction||'')}" placeholder="选择或填写派系"><datalist id="character-factions">${project.docs.filter(x=>x.type==='script'&&x.folder==='派系').map(x=>`<option value="${e(x.title)}">`).join('')}</datalist></label>${renderCharacterFixedFields(c)}${renderCharacterCustomFields(c)}</div></div></section><section class="char-panel"><div class="char-section-heading"><h2>三视图</h2><button class="btn primary" data-character-three-views ${busy?'disabled':''}>${icon('spark')}一键生成三视图</button></div><div class="char-views">${['正面','侧面','背面'].map(x=>slot('view-'+x,x)).join('')}</div></section><section class="char-panel"><div class="char-section-heading"><h2>表情 <small>${expressions.length} 种情绪</small></h2><div class="character-basic-actions"><button class="btn primary" data-character-all-expressions ${busy?'disabled':''}>${icon('spark')}一键生成全部表情</button><button class="btn subtle" data-char-add-expression>${icon('plus')}添加表情</button></div></div>${renderCharacterImageSettings(c)}<div class="char-emotions">${expressions.map(x=>slot('expression-'+x,x)).join('')}</div></section><section class="char-panel"><div class="char-section-heading"><h2>声线 <small>本地 IndexTTS 2.5</small></h2><button class="btn primary" data-tts-deploy>一键部署 TTS 2.5</button></div><p class="text-muted">部署版本：IndexTTS 2.5 · 保存到：${e(project.saveFolderName||nativeStore.root)}/本地TTS</p><div class="char-voice-config"><details class="tts-requirements"><summary>本地 TTS 配置提示 <span>点击查看配置与使用说明</span></summary><div class="tts-requirements-body"><p>采用本地 IndexTTS 2.5 模型生成语音，台词与参考声音在本机处理，无需云端 API。点击「一键部署 TTS 2.5」会在当前项目的「本地TTS」目录创建运行环境、下载并校验模型；服务就绪后即可添加参考声音并生成。</p><strong>基本配置建议</strong><ul><li>Windows 10 / 11，64 位系统</li><li>内存建议 16 GB 起，32 GB 更充裕</li><li>建议 NVIDIA 独立显卡，显存 8 GB 起，12 GB 及以上更稳妥；长台词可能需要更多显存</li><li>建议预留至少 30 GB 磁盘空间，用于模型、运行环境和缓存</li><li>首次准备组件需要联网下载；完整包准备完成后可本地运行。CPU 模式速度较慢</li></ul><small>以上为本软件的配置建议，尚非实测最低要求；性能取决于显卡、台词长度和生成参数。</small><h3>组件安装与使用说明</h3><p>点击「一键部署 TTS 2.5」在当前项目内准备环境与模型，部署日志保存在 本地TTS/logs。当前安装依赖本机已有基础包，完整离线发行包和全新电脑安装仍待完善。</p><a href="https://github.com/index-tts/index-tts" target="_blank" rel="noopener">INDEX TTS 官方说明</a></div></details><div class="voice-config-columns"><div class="voice-reference-column">${slot('reference','人物参考声音',true)}</div><div class="voice-settings-column"><div class="voice-service-row"><label class="char-field">本地服务地址<input data-char-field="ttsURL" value="${e(c.ttsURL||'http://127.0.0.1:9880')}" placeholder="http://127.0.0.1:9880"></label><button class="btn" data-char-check>检测服务</button></div><div class="voice-text-heading"><strong>试听台词</strong><button class="btn" data-voice-preview-text>按性格生成试听文本</button></div><label class="char-field">试听文本<textarea data-char-field="speech" rows="3" placeholder="输入需要人物说出的台词…">${e(c.speech||'')}</textarea></label><div class="voice-audition"><label>试听语气<select data-char-field="auditionEmotion">${CHARACTER_EMOTIONS.map(x=>`<option ${x===(c.auditionEmotion||'正常')?'selected':''}>${x}</option>`).join('')}</select></label><button class="btn primary" data-voice-audition data-char-generate="${e(c.auditionEmotion||'正常')}" ${voicePending?'disabled':''}>${voicePending?'生成中…':'生成并试听'}</button>${objectURLs.has(files['voice-'+(c.auditionEmotion||'正常')]?.fileId)?`<audio controls preload="none" src="${objectURLs.get(files['voice-'+(c.auditionEmotion||'正常')].fileId)}"></audio>`:''}</div><p class="text-muted">先生成或填写台词，再用参考声线合成试听；情绪效果以试听为准。</p></div></div></div><div class="char-emotions char-voices">${CHARACTER_EMOTIONS.map(x=>slot('voice-'+x,x,true)).join('')}</div></section>${!d.character&&parseMD(d.md).body.trim()?`<details class="char-panel"><summary>原有人物资料</summary><article class="document">${markdown(d.md)}</article></details>`:''}</div>`;
}
function localTTSURL(c){const u=new URL(c.ttsURL||'http://127.0.0.1:9880');if(u.protocol!=='http:'||!['127.0.0.1','localhost','[::1]'].includes(u.hostname)||u.username||u.password)throw Error('请填写本机 HTTP 服务地址');return u.origin;}
document.addEventListener('click',async ev=>{const target=ev.target.closest('[data-char-upload],[data-char-generate],[data-char-download],[data-char-check]');if(!target)return;const d=current(),owner=project;if(d?.type!=='character')return;try{d.character||={};const c=d.character;c.files||={};if(target.hasAttribute('data-char-check')){const r=await fetch(localTTSURL(c)+'/health',{signal:AbortSignal.timeout(5000)});if(!r.ok)throw Error('服务未就绪');const body=await r.json();if(body.model!=='IndexTTS2.5'||body.projectId!==owner.id)throw Error('未检测到 IndexTTS 2.5');toast('IndexTTS 2.5 已连接');return;}if(target.dataset.charDownload){const resource=displayedImage(c.files,target.dataset.charDownload);const f=resource&&await getFile(resource.fileId);if(!f)throw Error('文件缺失');download(f.blob,f.name);return;}if(target.dataset.charUpload){const key=target.dataset.charUpload,audio=target.dataset.audio==='true';fileDialog(audio?'audio/*':'image/png,image/jpeg,image/webp',async files=>{const f=files[0];if(!f)return;if(!f.type.startsWith(audio?'audio/':'image/'))throw Error('文件类型不正确');if(f.size>20*1024*1024)throw Error('文件不能超过 20 MB');const resource={fileId:await addFile(f,f.name),name:f.name,mime:f.type};if(audio)c.files[key]=resource;else stageImage(c.files,key,resource);d.updated=Date.now();await persist(owner);render();},false);return;}if(voicePending)return;if(!c.speech?.trim())throw Error('请先填写生成台词');if(!c.files.reference?.fileId)throw Error('请先上传人物参考声音');const reference=await getFile(c.files.reference.fileId);if(!reference)throw Error('请先上传人物参考声音');voicePending=true;render();try{const emotion=target.dataset.charGenerate;const r=await fetch(localTTSURL(c)+'/synthesize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId:owner.id,text:c.speech,emotion,reference:await blobDataURL(reference.blob),referenceName:reference.name}),signal:AbortSignal.timeout(600000)});if(!r.ok){const body=await r.json().catch(()=>({}));throw Error(body.error||'生成失败 HTTP '+r.status);}if(!r.headers.get('content-type')?.startsWith('audio/'))throw Error('服务未返回音频');const blob=await r.blob(),name=d.title+'-'+emotion+'.wav';if(c.files['voice-'+emotion])c.files['history:voice-'+emotion+':'+uid()]=c.files['voice-'+emotion];c.files['voice-'+emotion]={status:'pending',fileId:await addFile(blob,name),name,mime:'audio/wav'};d.updated=Date.now();await persist(owner);toast(emotion+'声线已生成');}finally{voicePending=false;render();if(target.hasAttribute('data-voice-audition'))document.querySelector('.voice-audition audio')?.play().catch(()=>{});}}catch(err){toast('本地声线：'+(err.message==='Failed to fetch'?'无法连接服务，请先启动本地 IndexTTS 2.5':err.message),true);}});

