    if(button.hasAttribute('data-char-image-submit')){const request=document.querySelector('#char-image-request').value.trim();if(!request)throw Error('请填写作图或修改要求');d.character.imageRequests||={};d.character.imageRequests[key]=request;const dimensions={width:document.querySelector('#char-ai-width').value,height:document.querySelector('#char-ai-height').value};imageParameters({...d.character.imageSettings,...dimensions});markDirty();await generateCharacterImage(d,key,button.dataset.label,request,dimensions);return;}
    if(characterImagePending?.docId===d.id&&characterImagePending.key===key)return;
