document.addEventListener('change',ev=>{const el=ev.target,key=el.dataset.skillSetting;if(!key)return;const settings=skillSettings(project);if(key==='width'||key==='height'){const value=Number(el.value);if(!Number.isInteger(value)||value<64||value>8192){el.value=settings[key];toast('图标尺寸请输入 64 至 8192 的整数',true);return;}settings[key]=value;}else if(key==='format'){if(!['png','webp','jpeg'].includes(el.value))return;settings.format=el.value;if(settings.format==='jpeg')settings.transparent=false;}else if(key==='transparent'){settings.transparent=el.value==='true';if(settings.transparent&&settings.format==='jpeg')settings.format='png';}else return;project.skillSettings=settings;markDirty();if(key==='format'||key==='transparent'){const format=document.querySelector('[data-skill-setting="format"]'),transparent=document.querySelector('[data-skill-setting="transparent"]');format.value=settings.format;format.querySelector('[value="jpeg"]').disabled=settings.transparent;transparent.value=String(settings.transparent);}});

async function openRecycleBin(){if(!await persist())return;const stored=await transaction('projects','readonly',store=>store.getAll());trashOwners=stored.map(p=>projects.find(x=>x.id===p.id)||archivedProjects.find(x=>x.id===p.id)||p);special='trash';closeModal();render();}
function renderRecycleBin(){const rows=[];for(const owner of trashOwners){if(owner.deleted||deletedProjectIDs().has(owner.id)){rows.push({owner,id:owner.id,kind:'project',title:owner.name,kindLabel:'项目',date:owner.deletedAt});continue;}for(const entry of owner.trash||[])rows.push({owner,id:entry.id,kind:entry.kind,title:entry.title||entry.data.title||entry.data.name||'未命名内容',kindLabel:entry.kind==='document'?(TYPES[entry.data.type]?.label||'内容'):entry.kind==='reference-image'?'参考图':entry.kind==='dialogue-line'?'对白':'人物字段',date:entry.deletedAt});}return '<div class="wide-page"><h2 class="panel-title">垃圾桶</h2><p class="panel-desc">删除的项目、内容、参考图和人物字段都保留在这里。恢复不会丢失资料；只有彻底删除才需要确认。</p>'+rows.map(row=>'<div class="history-card"><div class="history-head"><div><strong>'+e(row.title)+'</strong><small style="display:block;margin-top:6px">'+e(row.kindLabel)+' · '+e(row.owner.name)+' · '+when(row.date)+'</small></div><div style="display:flex;gap:8px"><button class="btn" data-action="restore-trash" data-owner="'+e(row.owner.id)+'" data-entry="'+e(row.id)+'" data-kind="'+row.kind+'">恢复</button><button class="btn danger" data-action="purge-trash" data-owner="'+e(row.owner.id)+'" data-entry="'+e(row.id)+'" data-kind="'+row.kind+'">彻底删除</button></div></div></div>').join('')+(rows.length?'':emptyState('垃圾桶为空','移入垃圾桶的内容会在这里显示。'))+'</div>';}
async function restoreTrashUI(button){const owner=trashOwners.find(p=>p.id===button.dataset.owner);if(!owner)return;if(button.dataset.kind==='project'){owner.deleted=false;owner.archived=false;owner.legacyRestored=true;markProjectDeleted(owner.id,false);if(!projects.some(p=>p.id===owner.id))projects.push(owner);}else restoreEntry(owner,button.dataset.entry);await putProject(owner);await warmFiles();await openRecycleBin();toast('已恢复');}
function confirmPurgeTrash(button){const owner=trashOwners.find(p=>p.id===button.dataset.owner);if(!owner)return;showModal('确认彻底删除','<p class="notice">此操作将从项目垃圾桶中永久移除所选资料，无法通过恢复按钮找回。磁盘上已保存的文件不受影响。</p>','<button class="btn" data-action="close-modal">取消</button><button class="btn danger" id="confirm-purge-trash">彻底删除</button>');document.querySelector('#confirm-purge-trash').onclick=async()=>{try{if(button.dataset.kind==='project'){await transaction('projects','readwrite',store=>store.delete(owner.id));projects=projects.filter(p=>p.id!==owner.id);archivedProjects=archivedProjects.filter(p=>p.id!==owner.id);markProjectDeleted(owner.id,false);}else{purgeEntry(owner,button.dataset.entry);await putProject(owner);}closeModal();await openRecycleBin();toast('已彻底删除');}catch(err){toast(err.message,true);}};}

