async function generateSkillBatch(){const count=Number(document.querySelector('#skill-batch-count').value),kind=document.querySelector('#skill-batch-kind').value,request=document.querySelector('#skill-batch-request').value.trim(),icons=document.querySelector('#skill-batch-icons').checked;if(!Number.isInteger(count)||count<1||count>30)throw Error('数量请输入 1 至 30 的整数');if(!request)throw Error('请填写生成要求');return submitGPT(current(),'设计 '+count+' 个'+kind+'，按字段创建技能候选，避免与已有技能重复。要求：'+request+(icons?'。同时使用 GPT 原生作图制作各个 ICON，保存实际图片为待修改。':''),{openEnded:true});}

