function ensureDialogue(d){if(!d.dialogue)d.dialogue={source:parseMD(d.md||'').body,lines:[]};d.dialogue.lines||=[];return d.dialogue;}
document.addEventListener('input',ev=>{const el=ev.target,d=current();if(d?.type!=='narrative'||dialogueRunning)return;if(el.hasAttribute('data-dialogue-source')){ensureDialogue(d).source=el.value;d.updated=Date.now();markDirty();}if(el.dataset.dialogueField==='text'){const l=ensureDialogue(d).lines.find(l=>l.id===el.dataset.line);if(l){l.text=el.value;l.error='';d.updated=Date.now();markDirty();}}});
document.addEventListener('change',async ev=>{const el=ev.target,d=current();if(d?.type!=='narrative'||dialogueRunning||!el.dataset.dialogueField)return;const l=ensureDialogue(d).lines.find(l=>l.id===el.dataset.line);if(!l)return;const field=el.dataset.dialogueField;if(!['text','emotion','characterId'].includes(field))return;l[field]=el.value;if(field==='characterId'){const c=project.docs.find(x=>x.id===l.characterId);if(c){l.speaker=c.character?.name||c.title;d.participants=[...new Set([...(d.participants||[]),c.id])];}}l.error='';d.updated=Date.now();await persist();render();});
document.addEventListener('click',async ev=>{const button=ev.target.closest('[data-dialogue-action],[data-dialogue-character]');if(!button)return;try{if(button.dataset.dialogueCharacter){const c=project.docs.find(x=>x.type==='character'&&x.id===button.dataset.dialogueCharacter);if(!c)throw Error('关联人物已被删除');await persist();selected=c.id;type='character';special=null;render();return;}const action=button.dataset.dialogueAction;if(action==='cancel'){dialogueController?.abort();return;}if(dialogueRunning)throw Error('请等待当前配音或拆分任务完成');const d=current();if(d?.type!=='narrative')return;const state=ensureDialogue(d),chars=project.docs.filter(x=>x.type==='character'),line=state.lines.find(l=>l.id===button.dataset.line);
 if(action==='import'){fileDialog('.md,.txt',async files=>{const file=files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('剧本文件请控制在 2 MB 内');state.source=await file.text();state.sourceName=file.name;state.candidate=parseDialogue(state.source,chars);d.updated=Date.now();await persist();render();toast('原文已保留，请检查拆分结果');},false);return;}
 if(action==='split'){if(!state.source?.trim())throw Error('请先导入或粘贴剧本');state.candidate=parseDialogue(state.source,chars);if(!state.candidate.length)throw Error('没有识别到台词，请使用 AI 识别或手动添加');}
 if(action==='ai-split'){await aiSplitDialogue(d);return;}
 if(action==='adopt'){const diff=dialogueDiff(state.lines,state.candidate||[]);for(const removed of diff.removed)recycle(project,'dialogue-line',removed,{docId:d.id,title:removed.speaker+'：'+removed.text.slice(0,30)});state.lines=diff.lines;d.participants=[...new Set([...(d.participants||[]),...(state.candidate||[]).map(l=>l.characterId).filter(Boolean)])];delete state.candidate;}
 if(action==='discard')delete state.candidate;
 if(action==='delete'&&line){recycle(project,'dialogue-line',line,{docId:d.id,index:state.lines.indexOf(line),title:line.speaker+'：'+line.text.slice(0,30)});state.lines=state.lines.filter(l=>l!==line);}
 if(action==='add')state.lines.push({id:uid(),speaker:'',characterId:'',emotion:'正常',text:''});
 if(action==='up'||action==='down'){const i=state.lines.indexOf(line),j=i+(action==='up'?-1:1);if(i>=0&&j>=0&&j<state.lines.length)[state.lines[i],state.lines[j]]=[state.lines[j],state.lines[i]];}
 if(action==='generate'||action==='batch'){await generateDialogueAudio(d,action==='generate'?[line]:state.lines.filter(l=>!audioCurrent(l,chars)));return;}
 if(action==='confirm-audio'){if(!line?.audio)throw Error('请先生成配音');if(!audioCurrent(line,chars))throw Error('台词或声线已变化，请重新生成后确认');line.audio.status='confirmed';line.audio.confirmedAt=Date.now();await putProject(project);render();return;}if(action==='download'){const file=line?.audio&&await getFile(line.audio.fileId);if(!file)throw Error('配音文件不存在');download(file.blob,file.name);return;}
 if(action==='export'){await exportDialogueAudio(d);return;}
 d.updated=Date.now();await persist();render();}catch(err){toast(err.message,true);}});
async function aiSplitDialogue(d){const state=ensureDialogue(d);if(!state.source?.trim())throw Error('请先填写剧本');return submitGPT(d,'识别逐句对白、人物与语气，不改写原文。在 dialogue.candidate 保存预览，不覆盖 lines 和已有音频。原文：'+state.source);}
async function generateDialogueAudio(d,lines){if(busy||voicePending)throw Error('请等待当前生成任务完成');if(!lines.length)return toast('所有对白已有最新配音');const owner=project;if(!await persist(owner))return;dialogueRunning=true;busy=true;dialogueController=new AbortController();const signal=dialogueController.signal;let job;render();try{job=await window.__NARRATIVE_RPC__('generate_dialogue_audio',{projectId:owner.id,docId:d.id,lineIds:lines.map(l=>l.id)});const cancel=()=>window.__NARRATIVE_RPC__('cancel_tts_job',{jobId:job.id}).catch(()=>{});signal.addEventListener('abort',cancel,{once:true});if(signal.aborted)await cancel();while(job.status==='running'){dialogueProgress='已生成 '+job.done+' / '+job.total+' 句'+(job.failed?'，失败 '+job.failed+' 句':'');if(project.id===owner.id)render();await new Promise(resolve=>setTimeout(resolve,1000));job=await window.__NARRATIVE_RPC__('tts_job_status',{jobId:job.id});}dialogueProgress='已生成 '+job.done+' 句，失败 '+job.failed+' 句'+(job.status==='cancelled'?'，已取消':'');if(job.errors?.length)toast(job.errors.map(x=>x.message||String(x)).join('；'),true);}finally{dialogueRunning=false;busy=false;dialogueController=null;const latest=(await nativeStore.allProjects()).find(p=>p.id===owner.id);if(latest){Object.assign(owner,latest);if(project.id===owner.id){project=owner;await warmFiles();}}render();}}

async function exportDialogueAudio(d){const chars=project.docs.filter(x=>x.type==='character'),copy=structuredClone(d),files=[];for(const [i,l] of (copy.dialogue?.lines||[]).entries()){if(!l.audio)continue;const file=await getFile(l.audio.fileId);if(!file)continue;const path='音频/'+String(i+1).padStart(4,'0')+'-'+safePath(l.speaker||'对白')+'-'+l.emotion+'.wav';l.audio.path=path;files.push({name:path,data:file.blob});}files.push({name:'对白.md',data:'# '+d.title+'\n\n'+dialogueMarkdown(copy,chars).replaceAll('../音频/','音频/')});files.push({name:'剧本资料.md',data:serializeMD(copy)});download(await createZIP(files),safePath(d.title)+'-对白与配音.zip');}
function showItemSettings(){const s=project.itemSettings||{};showModal('道具图标设置',`<div class="item-settings"><label class="char-field">图片格式<select data-item-setting="format">${['png','webp','jpeg'].map(f=>`<option value="${f}" ${f===String(s.format||'png').toLowerCase()?'selected':''}>${f.toUpperCase()}</option>`).join('')}</select></label><label class="char-field">宽度（px）<input data-item-setting="width" type="number" min="64" max="8192" value="${e(s.width||256)}"></label><label class="char-field">高度（px）<input data-item-setting="height" type="number" min="64" max="8192" value="${e(s.height||256)}"></label></div><p class="text-muted">修改自动保存，应用于后续 AI 生成和修改。已有图标保留原规格。</p>`,'<button class="btn primary" data-action="close-modal">完成</button>');}
function showItemIconEditor(d){if(busy)return toast('请等待当前 AI 任务完成',true);selected=d.id;const image=d.media?.mime?.startsWith('image/')?d.media:null;showModal(image?'AI 修改道具 ICON':'AI 生成道具 ICON',`<p class="notice">${e(d.details?.name||d.title)} · ${image?'将当前 ICON 作为参考图片提交给图片模型。':'依据道具资料与项目设定生成 ICON。'}</p>${image&&objectURLs.has(image.fileId)?`<img class="item-edit-preview" src="${objectURLs.get(image.fileId)}" alt="当前道具图标" data-file="${e(image.fileId)}">`:''}<label class="char-field">${image?'修改要求':'生成要求'}<textarea id="item-icon-request" rows="4" placeholder="描述外观、材质、配色和需要保留的特征…">${e(d.iconRequest||'')}</textarea></label><p class="text-muted">采用顶部「图标设置」的规格；结果设为待修改，旧图保留在历史版本。</p>`,`<button class="btn" data-item-upload="${e(d.id)}">导入已有图标</button><button class="btn primary" data-item-icon-submit="${e(d.id)}">${image?'提交 AI 修改':'开始生成'}</button>`);}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-item-icon-submit]');if(!b)return;const d=project.docs.find(d=>d.id===b.dataset.itemIconSubmit&&d.type==='item');if(!d)return;d.iconRequest=document.querySelector('#item-icon-request').value;markDirty();generateItemIcon(d).catch(err=>toast(err.message,true));});
