 if(el.hasAttribute('data-aggregate-table')){selectedTables[project.id+':'+el.dataset.aggregateType]=el.dataset.aggregateTable;type=el.dataset.aggregateType;special=null;if(!['icons','sounds'].includes(tab))tab='list';query='';linkedDocId='';delete galleryFilters.docId;gallerySelection.clear();soundSelection.clear();render();return;}
