document.addEventListener('change',ev=>{const el=ev.target;if(!el.hasAttribute('data-gallery-select'))return;if(el.checked)gallerySelection.add(el.dataset.gallerySelect);else gallerySelection.delete(el.dataset.gallerySelect);const count=document.querySelector('.review-count');if(count)count.textContent=count.textContent.replace(/已选 \d+ 项/,'已选 '+gallerySelection.size+' 项');});
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-gallery-select-all],[data-gallery-clear],[data-gallery-batch]');if(!el)return;try{
 if(el.hasAttribute('data-gallery-select-all')){for(const checkbox of document.querySelectorAll('[data-gallery-select]'))gallerySelection.add(checkbox.dataset.gallerySelect);render();return;}
 if(el.hasAttribute('data-gallery-clear')){gallerySelection.clear();soundSelection.clear();render();return;}
 const images=collectImages(project),visibleDocs=new Set((tab==='icons'&&aggregateType(type)?aggregateRows(project,type,activeTable()):project.docs).map(d=>d.id)),selected=[...gallerySelection].map(id=>id.startsWith('doc:')?{docId:id.slice(4),slot:'media',targetSlot:'media'}:images.find(r=>r.key===id||r.fileId===id)).filter(r=>r&&visibleDocs.has(r.docId));if(!selected.length)throw Error('请先选择素材或待生成条目');
 if(el.dataset.galleryBatch==='generate'){showModal('GPT 批量生成 / 修改','<p class="notice">已选 '+selected.length+' 项。逐项读取世界观、关联人物与当前素材，保留旧图；生成结果先待审核。</p><label class="char-field">统一修改要求<textarea id="gallery-batch-request" rows="4" placeholder="例如：统一为手绘风格，保持主体，去掉白边。"></textarea></label>','<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="gallery-batch-submit">提交给当前 GPT</button>');document.querySelector('#gallery-batch-submit').onclick=async()=>{try{const request=document.querySelector('#gallery-batch-request').value.trim();if(!request)throw Error('请填写生成或修改要求');const tasks=selected.map(r=>({docId:r.docId,fileId:r.fileId,slot:r.targetSlot||'media',note:r.fileId?imageRecords(project,r.fileId).find(x=>x.reviewNote)?.reviewNote||'':''}));await submitGPT(project.docs.find(d=>d.id===tasks[0].docId),'批量处理以下图片条目。每项先 prepare_image_request 读取世界观、关联人物与原图，使用宿主原生作图，然后 save_asset 保存真实图片至各项 docId 和 slot，状态待审核，保留旧图。不要重复创建道具或技能条目。统一要求：'+request+'\n任务：'+JSON.stringify(tasks),{targets:tasks.map(t=>({docId:t.docId,slot:t.slot}))});}catch(err){toast(err.message,true);}};return;}
 const targets=selected.filter(r=>r.fileId);if(!targets.length)throw Error('尚未生成图片，不能确认或退回');const backup=structuredClone(project);try{for(const r of targets)updateReview(project,r.fileId,{reviewStatus:el.dataset.galleryBatch},r.docId);if(!await persist())throw Error('批量审核保存失败');gallerySelection.clear();render();toast('已更新 '+targets.length+' 张图片');}catch(err){Object.assign(project,backup);throw err;}
 }catch(err){toast(err.message,true);}});
document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.audioNote){updateAudioReview(project,el.dataset.audioNote,{reviewNote:el.value});markDirty();}if(el.hasAttribute('data-audio-query')){const cursor=el.selectionStart;audioQuery=el.value;render();const input=document.querySelector('[data-audio-query]');input?.focus();input?.setSelectionRange(cursor,cursor);}});
document.addEventListener('change',ev=>{const el=ev.target;if(!el.hasAttribute('data-audio-select'))return;if(el.checked)audioSelection.add(el.dataset.audioSelect);else audioSelection.delete(el.dataset.audioSelect);const count=document.querySelector('.review-count');if(count)count.textContent=count.textContent.replace(/已选 \d+ 项/,'已选 '+audioSelection.size+' 项');});
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-audio-all],[data-audio-clear],[data-audio-status],[data-audio-batch]');if(!el)return;try{if(el.hasAttribute('data-audio-all')){for(const box of document.querySelectorAll('[data-audio-select]'))audioSelection.add(box.dataset.audioSelect);render();return;}if(el.hasAttribute('data-audio-clear')){audioSelection.clear();render();return;}const rows=collectAudio(project),targets=el.dataset.audioId?rows.filter(r=>r.fileId===el.dataset.audioId):rows.filter(r=>audioSelection.has(r.fileId));if(!targets.length)throw Error('请先选择音频');const state=el.dataset.audioStatus||el.dataset.audioBatch;
 if(state==='modify'){showModal('GPT 批量修改音频','<p class="notice">人物对白通过本地 IndexTTS 2.5 重新生成，保留旧音频。音乐与音效仅整理修改设计，不会伪造音频生成。</p><label class="char-field">统一修改要求<textarea id="audio-batch-request" rows="4"></textarea></label>','<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="audio-batch-submit">提交给 GPT</button>');document.querySelector('#audio-batch-submit').onclick=async()=>{try{const request=document.querySelector('#audio-batch-request').value.trim();if(!request)throw Error('请填写修改要求');await submitGPT(project.docs.find(d=>d.id===targets[0].docId),'批量处理音频修改，先读取世界观、关联人物、台词和原音频。保留旧文件与不相关台词。人物对白通过本地 IndexTTS 2.5，必须查询任务完成后才报告已生成；声线参考不足时说明缺项。音乐和音效没有合成服务，只更新设计要求，不声称已生成音频。统一要求：'+request+'\n目标：'+JSON.stringify(targets.map(r=>({docId:r.docId,fileId:r.fileId,type:r.type,note:imageRecords(project,r.fileId).find(x=>x.reviewNote)?.reviewNote||''}))));}catch(err){toast(err.message,true);}};return;}
 const backup=structuredClone(project);try{for(const r of targets)updateAudioReview(project,r.fileId,{reviewStatus:state});if(!await persist())throw Error('音频审核保存失败');render();}catch(err){Object.assign(project,backup);throw err;}
 }catch(err){toast(err.message,true);}});

