function markCharacterPending(d){if(d?.type!=='character')return;d.status='draft';const badge=document.querySelector('[data-character-status-label]');if(badge){badge.textContent='待修改';badge.className='char-image-status pending';}for(const b of document.querySelectorAll('[data-character-profile-status]'))b.setAttribute('aria-pressed',String(b.dataset.characterProfileStatus==='draft'));}
