function sheetNewRow(){const d={id:uid(),type,title:'未命名'+TYPES[type].label,folder:'默认分类',status:'draft',md:template(type,'未命名条目'),details:{tableId:activeTable()},refs:[],images:[],versions:[],updated:Date.now()};project.docs.push(d);return d;}
function sheetRows(table){return [...table.querySelectorAll('tbody tr')].map(tr=>[...tr.querySelectorAll('[data-plan-field]')].filter(el=>el.dataset.planField!=='tableId'));}
document.addEventListener('click',ev=>{if(!ev.target.closest('[data-sheet-add]'))return;sheetNewRow();query='';markDirty();render();const rows=sheetRows(document.querySelector('[data-sheet-type]'));rows.at(-1)?.[0]?.focus();});
document.addEventListener('keydown',ev=>{const el=ev.target,table=el.closest?.('[data-sheet-type]');if(!table||!el.dataset.planField||el.dataset.planField==='tableId')return;const rows=sheetRows(table),r=rows.findIndex(row=>row.includes(el)),c=rows[r]?.indexOf(el);if(ev.key==='Tab'&&!ev.isComposing){const next=ev.shiftKey?(c>0?rows[r][c-1]:rows[r-1]?.at(-1)):(rows[r][c+1]||rows[r+1]?.[0]);if(next){ev.preventDefault();next.focus();}return;}if(ev.key==='Enter'&&!ev.shiftKey&&!ev.isComposing){ev.preventDefault();if(rows[r+1])rows[r+1][c]?.focus();else{sheetNewRow();query='';markDirty();render();sheetRows(document.querySelector('[data-sheet-type]')).at(-1)?.[c]?.focus();}}});
document.addEventListener('paste',ev=>{const el=ev.target,table=el.closest?.('[data-sheet-type]'),text=ev.clipboardData?.getData('text/plain');if(!table||!el.dataset.planField||el.dataset.planField==='tableId'||!text||!/[\t\n\r]/.test(text))return;ev.preventDefault();try{const rows=sheetRows(table),r=rows.findIndex(row=>row.includes(el)),c=rows[r]?.indexOf(el),fields=rows[r].map(x=>x.dataset.planField),options=Object.fromEntries(rows[r].filter(x=>x.tagName==='SELECT').map(x=>[x.dataset.planField,[...x.options].map(o=>o.value)]));const docs=rows.map(row=>project.docs.find(d=>d.id===row[0]?.dataset.planId));const plan=planSheetPaste({text,rows:docs,fields,startRow:r,startColumn:c,options});for(let i=0;i<plan.newRows;i++)docs.push(sheetNewRow());for(const change of plan.changes){const d=docs[change.row];d.details||={};d.details[change.key]=change.value;if(change.key==='name')d.title=change.value.trim()||'未命名条目';d.updated=Date.now();}query='';markDirty();render();toast('已填入 '+plan.cells+' 个单元格'+(plan.newRows?'，新增 '+plan.newRows+' 行':''));}catch(err){toast('未粘贴：'+err.message,true);}});

document.addEventListener('click',ev=>{if(!ev.target.closest('[data-character-three-views]'))return;const d=current();if(d?.type!=='character')return;try{threeViewRequest(d);showModal('一键生成三视图','<p class="notice">参考当前人物主图，分别生成正面、侧面、背面三张独立图片。旧图保留，结果均为待修改。</p><label class="char-field">补充要求（可留空）<textarea id="three-view-request" rows="3" placeholder="例如：全身站姿，保持服装细节一致。"></textarea></label>','<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="three-view-submit">开始生成三视图</button>');document.querySelector('#three-view-submit').onclick=async()=>{try{await submitGPT(d,threeViewRequest(d,document.querySelector('#three-view-request').value),{targets:['正面','侧面','背面'].map(view=>({docId:d.id,slot:'view-'+view}))});}catch(err){toast(err.message,true);}};}catch(err){toast(err.message,true);}});

document.addEventListener('click',async ev=>{if(!ev.target.closest('[data-character-all-expressions]'))return;const d=current();if(d?.type!=='character')return;try{for(const input of document.querySelectorAll('[data-character-image-setting]'))updateCharacterImageSetting(input);await submitGPT(d,expressionBatchRequest(d,CHARACTER_EMOTIONS),{targets:[...new Set([...CHARACTER_EMOTIONS,...(d.character?.expressions||[])])].map(emotion=>({docId:d.id,slot:'expression-'+emotion}))});}catch(err){toast(err.message,true);}});

document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-tts-deploy]');if(!b)return;const projectId=project?.id;if(!projectId){toast('请先创建项目',true);return;}const request=action=>window.__NARRATIVE_RPC__('ui_storage',{operation:'tts_deploy',project:{action,projectId}});try{b.disabled=true;b.textContent='检查项目环境…';const check=await request('status');b.title=check.directory;if(check.ready){toast('当前项目的 IndexTTS 2.5 已就绪');return;}const result=await request(check.installed?'start':'install');toast(result.message);for(let i=0;i<300;i++){await new Promise(r=>setTimeout(r,2000));const state=await request('status');if(!b.isConnected||project?.id!==projectId)return;b.textContent=state.progress||'正在启动…';if(state.ready){toast('IndexTTS 2.5 已就绪，可配置参考声音并配音');return;}if(state.error)throw Error(state.error);}toast('部署仍在进行，可再次点击查看进度');}catch(err){toast(err.message,true);}finally{if(b.isConnected){b.disabled=false;b.textContent='一键部署 TTS 2.5';}}});

function showProjectOnboarding(){app.innerHTML=`<main class="wide-page" style="max-width:680px;margin:10vh auto"><h1>创建第一个项目</h1><p class="panel-desc">先设置项目名称和保存地址，再进入工作台。默认在当前对话的工作目录下建立项目文件夹。</p><section class="char-panel"><label class="char-field">项目名称<input id="onboarding-project-name" placeholder="例如：我的第一款游戏" maxlength="200"></label><label class="char-field">保存位置<input id="onboarding-project-directory" value="${e(nativeStore.defaultDirectory||'')}" placeholder="完整目录地址"></label><p class="text-muted">将在此目录下创建独立项目文件夹，按左侧菜单整理文档和素材。</p><button class="btn primary" data-onboarding-create>创建项目并进入</button></section></main>`;}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-onboarding-create]');if(!b)return;try{const name=document.querySelector('#onboarding-project-name').value.trim(),directory=document.querySelector('#onboarding-project-directory').value.trim();if(!name||!directory)throw Error('请填写项目名称和保存位置');b.disabled=true;const p=await nativeStore.createProject(name,directory);projects.push(p);project=p;type='script';selected=p.docs.find(d=>d.type==='script')?.id;tab='preview';special=null;localStorage.setItem('nw-active',p.id);render();toast('项目已创建，保存位置：'+p.saveFolderName);}catch(err){toast(err.message,true);b.disabled=false;}});

document.addEventListener('click',ev=>{if(!ev.target.closest('[data-voice-record]'))return;const d=current(),owner=project;if(d?.type!=='character')return;openVoiceRecorder({modal,showModal,toast,onSave:async blob=>{const name='人物-'+safePath(d.character?.name||d.title||'未命名人物')+'-参考声音.wav',fileId=await addFile(blob,name);snapshot(d,'录音替换参考声音前');d.character||={};d.character.files||={};d.character.files.reference={fileId,name,mime:'audio/wav'};d.updated=Date.now();await putProject(owner);render();}});});

document.addEventListener('click',ev=>{const b=ev.target.closest('[data-planning-batch]');if(!b)return;const targetType=b.dataset.planningBatch,label={item:'道具列表',skill:'技能列表',term:'技能词条'}[targetType];if(!label||busy)return;showModal('一键 AI 生成 · '+label,'<p class="notice">自动读取全部策划文档，生成完整字段并追加到当前列表。已有条目保留，新内容为待修改。</p><label class="char-field">生成数量（可留空）<input id="planning-batch-count" type="number" min="1" max="200" placeholder="自动覆盖策划涉及的全部内容"></label><label class="char-field">补充要求（可留空）<textarea id="planning-batch-request" rows="4" placeholder="例如：补齐所有战斗道具，并设计对应的数值与使用限制"></textarea></label>','<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="planning-batch-submit">开始生成并加入列表</button>');document.querySelector('#planning-batch-submit').onclick=async()=>{try{const prompt=planningBatchRequest(project,targetType,{count:document.querySelector('#planning-batch-count').value,request:document.querySelector('#planning-batch-request').value,tableId:activeTable()});const anchor=project.docs.find(d=>d.type===targetType)||project.docs.find(d=>d.type==='script')||project.docs[0];if(anchor)await submitGPT(anchor,prompt,{openEnded:true});else{if(typeof window.__NARRATIVE_CHAT__!=='function')throw Error('当前宿主未连接 GPT 对话');if(!await persist())return;closeModal();await window.__NARRATIVE_CHAT__({projectId:project.id,docId:'',revision:project._revision,prompt});toast('已发送到当前 GPT 对话');}}catch(err){toast(err.message,true);}};});

document.addEventListener('change',ev=>{if(!ev.target.hasAttribute('data-gallery-table'))return;selectedTables[project.id+':'+type]=ev.target.value;gallerySelection.clear();linkedDocId='';delete galleryFilters.docId;render();});

document.addEventListener('input',ev=>{if(!ev.target.hasAttribute('data-list-query'))return;const position=ev.target.selectionStart;query=ev.target.value;render();const input=document.querySelector('[data-list-query]');input?.focus();try{input?.setSelectionRange(position,position);}catch{}});
document.addEventListener('click',ev=>{if(!ev.target.closest('[data-list-search-clear]'))return;query='';render();document.querySelector('[data-list-query]')?.focus();});

function currentSoundRows(){return soundRows(project,type,{tableId:activeTable(),query,status:soundStatus}).filter(d=>!linkedDocId||d.id===linkedDocId);}
document.addEventListener('input',ev=>{const el=ev.target;if(el.hasAttribute('data-sound-query')){const cursor=el.selectionStart;query=el.value;render();const input=document.querySelector('[data-sound-query]');input?.focus();input?.setSelectionRange(cursor,cursor);}if(el.dataset.soundNote){const d=project.docs.find(d=>d.id===el.dataset.soundNote);if(d){d.details||={};d.details.soundReview||={status:'pending'};d.details.soundReview.note=el.value;markDirty();}}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.hasAttribute('data-sound-table')){selectedTables[project.id+':'+type]=el.value;soundSelection.clear();linkedDocId='';render();}else if(el.hasAttribute('data-sound-status-filter')){soundStatus=el.value;soundSelection.clear();render();}else if(el.hasAttribute('data-sound-select')){el.checked?soundSelection.add(el.dataset.soundSelect):soundSelection.delete(el.dataset.soundSelect);render();}});
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-sound-all],[data-sound-clear],[data-sound-batch],[data-sound-export],[data-sound-import]');if(!b)return;try{const rows=currentSoundRows();if(b.hasAttribute('data-sound-all')){rows.forEach(d=>soundSelection.add(d.id));render();return;}if(b.hasAttribute('data-sound-clear')){soundSelection.clear();render();return;}if(b.hasAttribute('data-sound-export')){download(new Blob([JSON.stringify(soundReviewReport(project,type,rows),null,2)],{type:'application/json'}),tableLabel(type)+'音效设计审核清单.json');return;}if(b.hasAttribute('data-sound-import')){const owner=project,ownerType=type,allowed=aggregateRows(owner,type,activeTable());fileDialog('.json,application/json',async files=>{const file=files[0];if(!file)return;if(file.size>4*1024*1024)throw Error('审核清单不能超过 4 MB');const count=applySoundReport(owner,ownerType,allowed,await file.text());await putProject(owner);render();toast('已导入 '+count+' 项设计审核记录');},false);return;}const selected=rows.filter(d=>soundSelection.has(d.id));if(!selected.length)throw Error('请先选择当前表中的条目');if(b.dataset.soundBatch==='generate'){showModal('批量生成音效设计','<p>当前音效模型尚未接入，本次只生成或修改声音设计要求，不会生成音频。</p><label class="char-field">统一要求（可留空）<textarea id="sound-batch-request" rows="3"></textarea></label>','<button class="btn" data-action="close-modal">取消</button><button class="btn primary" id="sound-batch-submit">生成设计要求</button>');document.querySelector('#sound-batch-submit').onclick=async()=>{try{await submitGPT(selected[0],'参考世界观、玩法及对应道具或技能设定，批量生成或修改音效设计。音效模型未接入，不声称已生成声音文件。保留图片、名称和其他字段。使用 save_content 更新 details.'+(type==='item'?'soundUse':'soundCast 和 soundHit')+'，每次使用最新 revision。统一要求：'+document.querySelector('#sound-batch-request').value+'\n条目：'+JSON.stringify(selected.map(d=>({docId:d.id,note:d.details?.soundReview?.note||''}))));}catch(err){toast(err.message,true);}};return;}for(const d of selected){d.details||={};d.details.soundReview={...d.details.soundReview,status:b.dataset.soundBatch};}if(!await persist())return;render();toast('已更新 '+selected.length+' 项音效设计状态');}catch(err){toast(err.message,true);}});

installUIEditor({current,select:id=>{selected=id;},showModal,urls:objectURLs,save:async doc=>{const owner=projects.find(p=>p.docs.includes(doc));if(!owner)throw Error('项目已关闭');doc.updated=Date.now();await putProject(owner);return true;},render,addFile,fileDialog,generate:requestGPTImage,submit:submitGPT,download,toast});

installStudioPanels({defaultDirectory:()=>nativeStore.defaultDirectory,adoptProject:p=>{projects.push(p);project=p;selected=p.docs[0]?.id;type=p.docs[0]?.type||'script';special=null;tab='preview';localStorage.setItem('nw-active',p.id);},generate:requestGPTImage,project:()=>project,current,modal:showModal,close:closeModal,save:putProject,render,toast,fileDialog,addFile,getFile,download,jobs:()=>{special='tasks';render();},goto:visitRelated,resume:(j,prompt)=>window.__NARRATIVE_CHAT__({projectId:project.id,docId:j.docId,revision:project._revision,prompt})});

document.addEventListener('click',ev=>{const b=ev.target.closest('[data-line-reference]');if(!b)return;const doc=current(),owner=project,line=doc?.dialogue?.lines?.find(l=>l.id===b.dataset.lineReference);if(!line)return;fileDialog('audio/*',async files=>{const f=files[0];if(!f)return;line.referenceAudio={fileId:await addFile(f,f.name),name:f.name,mime:f.type};await putProject(owner);render();},false);});

installTableTools({project:()=>project,modal:showModal,close:closeModal,render,save:putProject,toast,recycle:recycleDocument});
document.addEventListener('input',ev=>{const el=ev.target;if(!el.dataset.branchField)return;const d=current(),b=d?.details?.branches?.[Number(el.dataset.branchIndex)];if(b){b[el.dataset.branchField]=el.value;markDirty();}});
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-branch-add],[data-branch-remove]');if(!b)return;const d=current();if(d?.type!=='narrative')return;d.details||={};d.details.branches||=[];if(b.hasAttribute('data-branch-add'))d.details.branches.push({id:uid(),option:'',targetId:'',condition:'',result:''});else{const index=Number(b.dataset.branchRemove);d.details.branchHistory||=[];d.details.branchHistory.push(d.details.branches[index]);d.details.branches.splice(index,1);}await putProject(project);render();});

document.addEventListener('change',ev=>{const el=ev.target;if(!el.dataset.ttsParam)return;const l=current()?.dialogue?.lines?.find(l=>l.id===el.dataset.line);if(!l)return;const value=Number(el.value);if(!Number.isFinite(value)||value<Number(el.min)||value>Number(el.max)){toast('参数超出范围',true);return;}l.ttsSettings||={};l.ttsSettings[el.dataset.ttsParam]=value;markDirty();});

window.addEventListener('unhandledrejection',event=>{toast(event.reason?.message||'操作未完成，请重试',true);});

document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-char-confirm-voice]');if(!el)return;const owner=project,d=current(),r=d?.character?.files?.[el.dataset.charConfirmVoice];if(!r)return;r.status='confirmed';r.confirmedAt=Date.now();await putProject(owner);render();});
